  const [isSearching, setIsSearching] = useState(false)
  const [searchFailed, setSearchFailed] = useState(false)
  const [retryTick, setRetryTick] = useState(0)
  const [showLibraryPlaylists, setShowLibraryPlaylists] = useState(true)
  const [showNotifications, setShowNotifications] = useState(false)
  const [isFullscreen, setIsFullscreen] = useState(false)
  const [notifPermission, setNotifPermission] = useState<NotificationPermission | 'unsupported'>('default')

  /** Anchor for the floating activity menu, and the layer it is painted into. */
  const bellRef = useRef<HTMLButtonElement>(null)
  const [overlayHost, setOverlayHost] = useState<HTMLElement | null>(null)
  const [notifAnchor, setNotifAnchor] = useState<{ top: number; left: number } | null>(null)

  const [selectedTrackDetail, setSelectedTrackDetail] = useState<Track | null>(null)
  const [selectedArtistName, setSelectedArtistName] = useState<string | null>(null)
  const [artistBanner, setArtistBanner] = useState<string>()

  /** `tab:query` already loaded, so switching back doesn't refetch. */
  const loadedSearchRef = useRef('')

  const { playTrack, currentTrack, playerState } = useCatMusicPlayer()
  const { favorites, playlists, history, createPlaylist, deletePlaylist, clearHistory } = useLibrary()
  const { t } = useLanguage()

  // The whole plugin is coloured by what is playing; fall back to the featured
  // track's art so the shell is never a flat grey before the first play.
  const accent = useCatMusicAccent()
  useAccentSource(currentTrack?.artworkUrl ?? SEED_TRACKS[3]?.artworkUrl)

  const featuredTrack = currentTrack ?? SEED_TRACKS[3]

  useEffect(() => {
    const artist = featuredTrack.artist
    if (!artist) return
    const controller = new AbortController()
    fetch(`/api/youtube/channel?name=${encodeURIComponent(artist)}`, { signal: controller.signal })
      .then((res) => (res.ok ? res.json() : null))
      .then((data) => {
        if (data?.channel?.bannerUrl) setArtistBanner(data.channel.bannerUrl)
      })
      .catch(() => {
        // Includes the abort on unmount or a featured-track change.
      })
    return () => controller.abort()
  }, [featuredTrack.artist])

  useEffect(() => {
    if (typeof window === 'undefined') return
    setNotifPermission('Notification' in window ? Notification.permission : 'unsupported')
  }, [])

  useEffect(() => {
    return subscribeFullscreenChange(() => {
      setIsFullscreen(isFullscreenActive())
    })
  }, [])

  // A layer of our own, outside the React-managed tree, so nothing the shell
  // re-renders can drop it. It normally hangs off `document.body`; if a browser
  // promoted an element to fullscreen it moves inside that element, because the
  // top layer paints only that subtree.
  useEffect(() => {
    const host = document.createElement('div')
    host.setAttribute('data-cm-overlay', '')
    const attach = () => {
      const parent = getFullscreenElement() ?? document.body
      if (host.parentElement !== parent) parent.appendChild(host)
    }
    attach()
    setOverlayHost(host)
    const unsubscribe = subscribeFullscreenChange(attach)
    return () => {
      unsubscribe()
      host.remove()
    }
  }, [])

  /**
   * Pins the activity menu under the bell in viewport coordinates, clamped so it
   * can never hang off an edge of the window. It is `position: fixed` in its own
   * layer rather than absolutely positioned inside the header, so no ancestor's
   * `overflow: hidden` or stacking context can clip or bury it.
   */
  const measureNotifications = useCallback(() => {
    const anchor = bellRef.current
    if (!anchor) return null
    const rect = anchor.getBoundingClientRect()
    const maxLeft = Math.max(NOTIF_MENU_MARGIN, window.innerWidth - NOTIF_MENU_WIDTH - NOTIF_MENU_MARGIN)
    return {
      // Right edge of the panel lines up with the right edge of the button.
      left: Math.min(Math.max(NOTIF_MENU_MARGIN, rect.right - NOTIF_MENU_WIDTH), maxLeft),
      top: Math.min(rect.bottom + 8, Math.max(NOTIF_MENU_MARGIN, window.innerHeight - 120)),
    }
  }, [])

  // Measured in the click handler, not in an effect: both updates batch into the
  // same render, so the menu is never painted at a stale position first.
  const toggleNotifications = useCallback(() => {
    setShowNotifications((open) => {
      if (!open) setNotifAnchor(measureNotifications())
      return !open
    })
  }, [measureNotifications])

  useEffect(() => {
    if (!showNotifications) return

    const reposition = () => setNotifAnchor(measureNotifications())
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setShowNotifications(false)
        bellRef.current?.focus()
      }
    }

    window.addEventListener('resize', reposition)
    // Capture phase: the menu has to follow the button when any scroller moves.
    window.addEventListener('scroll', reposition, true)
    window.addEventListener('keydown', onKeyDown)
    return () => {
      window.removeEventListener('resize', reposition)
      window.removeEventListener('scroll', reposition, true)
      window.removeEventListener('keydown', onKeyDown)
    }
  }, [showNotifications, measureNotifications])

  useEffect(() => {
    if (!isFullscreen) return
    const previousOverflow = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        setIsFullscreen(false)
        exitDocumentFullscreen().catch(() => {})
      }
    }
    window.addEventListener('keydown', onKeyDown)
    return () => {
      document.body.style.overflow = previousOverflow
      window.removeEventListener('keydown', onKeyDown)
    }
  }, [isFullscreen])

  const requestNotifications = async () => {
    if (!('Notification' in window)) return
    const permission = await Notification.requestPermission()
    setNotifPermission(permission)
  }

  const toggleFullscreen = async () => {
    const root = rootRef.current
    if (!root) return

    if (isFullscreen) {
      setIsFullscreen(false)
      try {
        await exitDocumentFullscreen()
      } catch {
        // CSS mode exits via state
      }
      return
    }

    setIsFullscreen(true)
    try {
      await requestElementFullscreen(root)
    } catch {
      // Immersive CSS mode (fixed inset-0 z-30) still applies via isFullscreen state
    }
  }

  const applySearchResults = useCallback((tab: SearchTab, results: unknown[]) => {
    if (tab === 'songs') setSongResults(results as Track[])
    else if (tab === 'playlists') setPlaylistResults(results as YtPlaylist[])
    else setChannelResults(results as YtChannel[])
  }, [])

  // Only the visible tab is fetched. Firing all three per keystroke tripled the
  // upstream traffic for results the user usually never looked at.
  useEffect(() => {
    const query = searchQuery.trim()
    if (query.length < 2) {
      setSongResults([])
      setPlaylistResults([])
      setChannelResults([])
      setIsSearching(false)
      setSearchFailed(false)
      loadedSearchRef.current = ''
      return
    }

    const key = `${searchTab}:${query}`
    if (loadedSearchRef.current === key) return

    const controller = new AbortController()
    setIsSearching(true)
    setSearchFailed(false)

    const timer = setTimeout(async () => {
      try {
        const res = await fetch(
          `/api/youtube/search?q=${encodeURIComponent(query)}&type=${SEARCH_TYPE_BY_TAB[searchTab]}`,
          { signal: controller.signal },
        )
        const data = await res.json().catch(() => ({}))
        if (controller.signal.aborted) return

        if (!res.ok) {
          // 502 means YouTube is unreachable, which is not the same as "nothing
          // matched" — the empty state would otherwise lie about it.
          setSearchFailed(true)
          applySearchResults(searchTab, [])
          return
        }

        applySearchResults(searchTab, Array.isArray(data.results) ? data.results : [])
        loadedSearchRef.current = key
      } catch (err) {
        if ((err as Error)?.name === 'AbortError') return
        setSearchFailed(true)
        applySearchResults(searchTab, [])
      } finally {
        if (!controller.signal.aborted) setIsSearching(false)
      }
    }, 350)

    return () => {
      clearTimeout(timer)
      // Abort in flight: a slow response for an old query used to land after a
      // newer one and overwrite it.
      controller.abort()
    }
  }, [searchQuery, searchTab, retryTick, applySearchResults])

  const retrySearch = useCallback(() => {
    loadedSearchRef.current = ''
    setRetryTick((n) => n + 1)
  }, [])

  const localFiltered = useMemo(() => {
    const needle = searchQuery.trim().toLowerCase()
    return SEED_TRACKS.filter((track) => {
      const matchesQuery =
        !needle ||
        track.title.toLowerCase().includes(needle) ||
        track.artist.toLowerCase().includes(needle)
      const matchesGenre = selectedGenre === ALL_GENRES || track.genre === selectedGenre
      return matchesQuery && matchesGenre
    })
  }, [searchQuery, selectedGenre])

  const finalSongResults = searchQuery.trim().length >= 2 && songResults.length > 0 ? songResults : localFiltered
  const favoriteTracks = useMemo(() => {
    const seen = new Set<string>()
    return favorites.filter((t) => {
      if (!t.id || seen.has(t.id)) return false
      seen.add(t.id)
      return true
    })
  }, [favorites])

  const greeting = useMemo(() => {
    const h = new Date().getHours()
    if (h < 12) return t.goodMorning
    if (h < 19) return t.goodAfternoon
    return t.goodEvening
  }, [t])

  const handleCreatePlaylist = (e: React.FormEvent) => {
    e.preventDefault()
    if (!newPlName.trim()) return
    createPlaylist(newPlName.trim())
    setNewPlName('')
    setNewPlaylistOpen(false)
  }

  const selectedPlaylist = playlists.find((p) => p.id === selectedPlaylistId)

  /**
   * The plugin shell. Everything visual hangs off `.cm-root`, whose inline
   * custom properties carry the colour sampled from the current cover art —
   * so the aurora, every accent and every glow shift with the music instead
   * of sitting on a fixed green.
   */
  const withBackground = (children: React.ReactNode) => (
    <div
      ref={rootRef}
      style={accentVars(accent)}
      className={`cm-root cm-grain relative h-full w-full overflow-hidden text-white ${
        isFullscreen ? 'fixed inset-0 z-30 !h-dvh !w-dvw rounded-none' : ''
      }`}
    >
      <div className="cm-aurora" data-idle={!playerState.isPlaying} aria-hidden="true">
        {/* The cover art itself, blown up and blurred — free texture that is
            always in key with the accent because it *is* the source of it. */}
        {currentTrack?.artworkUrl && (
          <img src={currentTrack.artworkUrl} alt="" className="cm-immersive-bg" />
        )}
        <span className="cm-blob cm-blob-1" />
        <span className="cm-blob cm-blob-2" />
        <span className="cm-blob cm-blob-3" />
      </div>
      <div className="relative z-10 flex h-full flex-col">
        {children}
      </div>
    </div>
  )

  if (selectedTrackDetail) {
    return withBackground(
      <TrackDetailView
        track={selectedTrackDetail}
        onBack={() => setSelectedTrackDetail(null)}
        onSelectArtist={(artistName) => {
          setSelectedTrackDetail(null)
          setSelectedArtistName(artistName)
        }}
      />
    )
  }

  if (selectedArtistName) {
    return withBackground(
      <ArtistDetailView
        artistName={selectedArtistName}
        onBack={() => setSelectedArtistName(null)}
        onSelectTrack={(track) => {
          setSelectedArtistName(null)
          setSelectedTrackDetail(track)
        }}
      />
    )
  }

  const sidebarWidgets = (
    <div className="flex h-full min-h-0 flex-col gap-3">
      <GlassPanel variant="strong" className="shrink-0 space-y-0.5 rounded-[24px] p-3">
        <NavButton active={activeTab === 'home'} onClick={() => setActiveTab('home')} icon={Home} label={t.homeTab} />
        <NavButton active={activeTab === 'explore'} onClick={() => setActiveTab('explore')} icon={Search} label={t.exploreTab} />
        <NavButton active={activeTab === 'library'} onClick={() => setActiveTab('library')} icon={Library} label={t.libraryTab} />
      </GlassPanel>

      <GlassPanel variant="strong" className="flex min-h-0 flex-1 flex-col overflow-hidden rounded-[24px] p-3">
        <div className="flex items-center justify-between px-1 mb-2">
          <button
            onClick={() => setShowLibraryPlaylists(!showLibraryPlaylists)}
            className="flex items-center gap-1 text-[11px] font-bold uppercase tracking-wider text-white/40 hover:text-white/70 transition-colors"
          >
            <ChevronDown className={`size-3 transition-transform ${showLibraryPlaylists ? '' : '-rotate-90'}`} />
            {t.yourPlaylists}
          </button>
          <button
            onClick={() => setNewPlaylistOpen(true)}
            className="rounded-xl p-1 text-white/40 hover:bg-white/10 hover:text-white transition-colors"
            title={t.newPlaylist}
          >
            <Plus className="size-3.5" />
          </button>
        </div>
        {showLibraryPlaylists && (
          <div className="flex-1 overflow-y-auto thin-scroll space-y-0.5">
            {playlists.map((pl) => (
              <button
                key={pl.id}
                onClick={() => {
                  setActiveTab('library')
                  setSelectedPlaylistId(pl.id)
                }}
                className="flex w-full items-center gap-2 rounded-xl px-2 py-2 text-left text-[12px] text-white/50 hover:bg-white/5 hover:text-white transition-colors"
              >
                <ListMusic className="size-3.5 shrink-0 text-[var(--cm-accent)]" />
                <span className="truncate flex-1">{pl.name}</span>
                <span className="text-[10px] text-white/25 shrink-0">{pl.tracks.length}</span>
              </button>
            ))}
            {playlists.length === 0 && (
              <p className="px-2 py-2 text-[11px] text-white/30">{t.noPlaylists}</p>
            )}
          </div>
        )}
      </GlassPanel>
    </div>
  )

  return withBackground(
    <>
      <header className="shrink-0 flex items-center gap-3 px-4 py-3 md:px-6">
          <span className="flex shrink-0 items-center gap-2">
            <span
              aria-hidden
              className="flex size-7 items-center justify-center rounded-xl bg-gradient-to-br from-[var(--cm-accent-hi)] to-[var(--cm-accent-lo)] text-[#08090b] shadow-[0_8px_20px_-8px_var(--cm-halo)]"
            >
              <Music className="size-3.5" />
            </span>
            <span className="text-base font-black tracking-tight">CatMusic</span>
            {playerState.isPlaying && (
              <span className="cm-eq ml-0.5 h-3.5 text-[var(--cm-accent-hi)]" aria-hidden>
                <i /><i /><i /><i />
              </span>
            )}
          </span>

          <div className="flex-1 max-w-xl mx-auto">
            <div className="relative" role="search">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 size-4 text-white/35 z-10 pointer-events-none" />
              <input
                type="search"
                placeholder={t.searchMusicPlaceholder}
                aria-label={t.searchMusicPlaceholder}
                value={searchQuery}
                onChange={(e) => {
                  setSearchQuery(e.target.value)
                  if (e.target.value.trim().length >= 2) setActiveTab('explore')
                }}
                className="cm-glass w-full rounded-full pl-11 pr-10 py-2.5 text-[13px] text-white placeholder:text-white/35 transition-all focus:outline-none focus:border-[var(--cm-accent-edge)] focus:shadow-[0_0_0_4px_var(--cm-accent-veil)] [&::-webkit-search-cancel-button]:hidden"
              />
              {searchQuery && (
                <button
                  type="button"
                  onClick={() => setSearchQuery('')}
                  aria-label={t.clearSearch}
                  className="absolute right-3 top-1/2 -translate-y-1/2 rounded-full p-1 text-white/40 hover:text-white hover:bg-white/10 transition-colors"
                >
                  <X className="size-3.5" />
                </button>
              )}
            </div>
          </div>

          <div className="hidden md:flex items-center gap-1 shrink-0">
            <button
              ref={bellRef}
              type="button"
              onClick={toggleNotifications}
              aria-label={t.recentActivity}
              aria-expanded={showNotifications}
              aria-haspopup="dialog"
              className={`cm-focus rounded-full p-2 transition-colors ${
                showNotifications
                  ? 'cm-tint text-[var(--cm-accent-hi)]'
                  : 'text-white/40 hover:bg-white/10 hover:text-white'
              }`}
            >
              <Bell className="size-4" />
            </button>
            <button
              type="button"
              onClick={() => void toggleFullscreen()}
              aria-label={isFullscreen ? t.exitFullscreen : t.enterFullscreen}
              aria-pressed={isFullscreen}
              className={`cm-focus rounded-full p-2 transition-colors ${
                isFullscreen
                  ? 'cm-tint text-[var(--cm-accent-hi)]'
                  : 'text-white/40 hover:bg-white/10 hover:text-white'
              }`}
            >
              {isFullscreen ? <Minimize2 className="size-4" /> : <Maximize2 className="size-4" />}
            </button>
          </div>
        </header>

        {/* Body */}
        <div className="flex flex-1 min-h-0 gap-3 px-3 pb-28 md:px-4 md:pb-24">
          {/* Left sidebar - desktop */}
          <aside className="hidden h-full w-[220px] shrink-0 flex-col min-h-0 lg:flex">
            {sidebarWidgets}
          </aside>

          {/* Main scroll area */}
          <main className="flex-1 min-w-0 overflow-y-auto thin-scroll">
            {activeTab === 'home' && (
              <HomeDashboard
                greeting={greeting}
                featuredTrack={featuredTrack}
                favoritesCount={favorites.length}
                playlistsCount={playlists.length}
                historyCount={history.length}
                artistBannerUrl={artistBanner}
                onPlayFeatured={() => playTrack(featuredTrack, SEED_TRACKS)}
                onSelectArtist={setSelectedArtistName}
                onSelectTrack={setSelectedTrackDetail}
              />
            )}

            {/* ======= EXPLORE TAB ======= */}
            {activeTab === 'explore' && (
              <div className="space-y-4 pb-4">
                {!searchQuery && (
                  <>
                    <GlassPanel className="p-4 md:p-5">
                      <h3 className="text-sm font-bold text-white/80 mb-3 flex items-center gap-2">
                        <Radio className="size-4 text-[var(--cm-accent-hi)]" />
                        {t.exploreByGenre}
                      </h3>
                      <div className="flex flex-wrap items-center gap-2">
                        {GENRES.map((g) => (
                          <button
                            key={g}
                            onClick={() => {
                              setSelectedGenre(g)
                              setSearchQuery(g === ALL_GENRES ? '' : g)
                            }}
                            aria-pressed={selectedGenre === g}
                            className={`rounded-full px-4 py-2 text-[12.5px] font-semibold transition-all ${
                              selectedGenre === g && searchQuery
                                ? 'bg-[var(--cm-accent-hi)] text-[#08090b] shadow-lg shadow-[var(--cm-halo)]'
                                : 'bg-white/[0.08] text-white/70 hover:bg-white/[0.14] hover:text-white'
                            }`}
                          >
                            {g === ALL_GENRES ? t.allGenres : g}
                          </button>
                        ))}
                      </div>
                    </GlassPanel>

                    <GlassPanel className="p-4 md:p-5">
                      <h3 className="text-sm font-bold text-white/80 mb-4 flex items-center gap-2">
                        <Sparkles className="size-4 text-[var(--cm-accent-hi)]" />
                        {t.trending}
                      </h3>
                      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-5 gap-3">
                        {SEED_TRACKS.slice(0, 10).map((t) => (
                          <TrackCard key={t.id} track={t} queue={SEED_TRACKS} />
                        ))}
                      </div>
                    </GlassPanel>
                  </>
                )}

                {searchQuery && searchQuery.trim().length >= 2 && (
                  <GlassPanel className="overflow-hidden p-3">
                    {/* Segmented control rather than underlined tabs: the sliding
                        accent pill reads as one control instead of three links. */}
                    <div className="px-4 pt-3">
                      <div className="cm-seg" role="tablist" aria-label={t.searchResults}>
                        {(['songs', 'playlists', 'artists'] as SearchTab[]).map((type) => (
                          <button
                            key={type}
                            role="tab"
                            id={`cm-search-tab-${type}`}
                            aria-selected={searchTab === type}
                            aria-controls={`cm-search-panel-${type}`}
                            onClick={() => setSearchTab(type)}
                            className={`cm-focus px-4 py-2 text-[12.5px] font-bold ${
                              searchTab === type ? '' : 'text-white/45 hover:text-white/80'
                            }`}
                          >
                            {type === 'songs' ? t.songs : type === 'playlists' ? t.playlists : t.artists}
                          </button>
                        ))}
                      </div>
                    </div>

                    {searchFailed && (
                      <div
                        role="alert"
                        className="mx-4 mt-3 flex flex-wrap items-center justify-between gap-3 rounded-2xl border border-rose-400/20 bg-rose-500/10 px-4 py-3"
                      >
                        <p className="text-[13px] text-rose-100">{t.upstreamError}</p>
                        <button
                          onClick={retrySearch}
                          className="rounded-full bg-white/10 px-4 py-1.5 text-[12.5px] font-semibold text-white transition-colors hover:bg-white/20"
                        >
                          {t.retry}
                        </button>
                      </div>
                    )}

                    {searchTab === 'songs' && (
                      <div role="tabpanel" id="cm-search-panel-songs" aria-labelledby="cm-search-tab-songs">
                        {isSearching ? (
                          <RowSkeletons label={t.searchingSongs} />
                        ) : finalSongResults.length > 0 ? (
                          <div className="divide-y divide-white/[0.06]">
                            {finalSongResults.map((song, idx) => (
                              <TrackRow
                                key={`${song.id}-${idx}`}
                                track={song}
                                index={idx + 1}
                                queue={finalSongResults}
                                onSelectArtist={(a) => setSelectedArtistName(a)}
                                onSelectTrack={(tr) => setSelectedTrackDetail(tr)}
                              />
                            ))}
                          </div>
                        ) : (
                          <div className="py-16 text-center">
                            <Music className="mx-auto size-10 text-white/20 mb-3" />
                            <p className="text-sm text-white/40">{t.noSongsFoundSearch}</p>
                          </div>
                        )}
                      </div>
                    )}

                    {searchTab === 'playlists' && (
                      <div className="p-4" role="tabpanel" id="cm-search-panel-playlists" aria-labelledby="cm-search-tab-playlists">
                        {isSearching ? (
                          <CardSkeletons
                            label={t.searchingPlaylists}
                            count={8}
                            className="grid grid-cols-1 gap-3 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4"
                          />
                        ) : playlistResults.length > 0 ? (
                          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                            {playlistResults.map((pl, idx) => (
                              <button
                                key={pl.id}
                                onClick={() =>
                                  setSelectedTrackDetail({
                                    id: pl.id,
                                    title: pl.title,
                                    artist: pl.artist,
                                    durationSeconds: 0,
                                    artworkUrl: pl.coverUrl,
                                    source: 'youtube',
                                  } as Track)
                                }
                                style={{ '--i': idx } as CSSProperties}
                                className="cm-glass cm-lift cm-rise cm-focus group flex flex-col gap-3 rounded-2xl p-3 text-left"
                              >
                                <div className="relative aspect-square w-full overflow-hidden rounded-xl bg-white/5">
                                  <img src={pl.coverUrl} alt={pl.title} className="size-full object-cover transition-transform duration-500 group-hover:scale-[1.07]" />
                                  <div className="absolute inset-0 flex items-center justify-center bg-gradient-to-t from-black/70 via-black/10 to-transparent opacity-0 transition-opacity group-hover:opacity-100">
                                    <span className="cm-btn cm-btn-primary size-11 translate-y-2 transition-transform duration-300 group-hover:translate-y-0">
                                      <Play className="size-5 fill-current" />
                                    </span>
                                  </div>
                                </div>
                                <div>
                                  <h4 className="truncate text-[13px] font-bold text-white group-hover:text-[var(--cm-accent-hi)] transition-colors">{pl.title}</h4>
                                  <p className="truncate text-[11px] text-white/50 mt-0.5">{pl.artist}</p>
                                </div>
                              </button>
                            ))}
                          </div>
                        ) : (
                          <div className="py-16 text-center">
                            <ListMusic className="mx-auto size-10 text-white/20 mb-3" />
                            <p className="text-sm text-white/40">{t.noPlaylistsFound}</p>
                          </div>
                        )}
                      </div>
                    )}

                    {searchTab === 'artists' && (
                      <div className="p-4 pt-3" role="tabpanel" id="cm-search-panel-artists" aria-labelledby="cm-search-tab-artists">
                        {isSearching ? (
                          <CardSkeletons
                            label={t.searchingArtists}
                            round
                            count={6}
                            className="grid grid-cols-2 gap-3 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6"
                          />
                        ) : channelResults.length > 0 ? (
                          <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
                            {channelResults.map((ch, idx) => (
                              <button
                                key={ch.id}
                                onClick={() => setSelectedArtistName(ch.name)}
                                style={{ '--i': idx } as CSSProperties}
                                className="cm-glass cm-lift cm-rise cm-focus group flex flex-col items-center gap-3 rounded-2xl p-4 text-center"
                              >
                                <div className="size-20 overflow-hidden rounded-full ring-2 ring-white/10 transition-all group-hover:ring-[var(--cm-accent-edge)] group-hover:shadow-[0_0_0_6px_var(--cm-accent-veil)]">
                                  <img src={ch.avatarUrl} alt={ch.name} className="size-full object-cover" />
                                </div>
                                <h4 className="w-full truncate text-[13px] font-bold text-white group-hover:text-[var(--cm-accent-hi)] transition-colors">{ch.name}</h4>
                              </button>
                            ))}
                          </div>
                        ) : (
                          <div className="py-16 text-center">
                            <User className="mx-auto size-10 text-white/20 mb-3" />
                            <p className="text-sm text-white/40">{t.noArtistsFound}</p>
                          </div>
                        )}
                      </div>
                    )}
                  </GlassPanel>
                )}
              </div>
            )}

            {/* ======= LIBRARY TAB ======= */}
            {activeTab === 'library' && (
              <div className="space-y-4 pb-4">
                <GlassPanel className="p-4 md:p-5">
                  <h1 className="text-2xl font-black flex items-center gap-2">
                    <Library className="size-6 text-[var(--cm-accent-hi)]" />
                    {t.yourLibrary}
                  </h1>
                  <p className="text-sm text-white/50 mt-1">{t.libraryDesc}</p>

                  <div className="mt-4 flex flex-wrap items-center gap-1 rounded-2xl bg-white/[0.04] p-1 border border-white/[0.06] w-fit">
                    <button
                      onClick={() => setSelectedPlaylistId(null)}
                      className={`rounded-xl px-4 py-2 text-[12.5px] font-semibold transition-all ${!selectedPlaylistId ? 'bg-[var(--cm-accent-hi)] text-[#08090b] shadow-lg shadow-[var(--cm-halo)]' : 'text-white/50 hover:text-white'}`}
                    >
                      {t.myPlaylists} ({playlists.length})
                    </button>
                    <button
                      onClick={() => setSelectedPlaylistId('favorites')}
                      className={`rounded-xl px-4 py-2 text-[12.5px] font-semibold transition-all ${selectedPlaylistId === 'favorites' ? 'bg-[var(--cm-accent-hi)] text-[#08090b] shadow-lg shadow-[var(--cm-halo)]' : 'text-white/50 hover:text-white'}`}
                    >
                      <Heart className="size-3.5 inline mr-1" />
                      {t.favorites} ({favorites.length})
                    </button>
                    <button
                      onClick={() => setSelectedPlaylistId('history')}
                      className={`rounded-xl px-4 py-2 text-[12.5px] font-semibold transition-all ${selectedPlaylistId === 'history' ? 'bg-[var(--cm-accent-hi)] text-[#08090b] shadow-lg shadow-[var(--cm-halo)]' : 'text-white/50 hover:text-white'}`}
                    >
                      <Clock className="size-3.5 inline mr-1" />
                      {t.history}
                    </button>
                  </div>
                </GlassPanel>

                {!selectedPlaylistId && (
                  <GlassPanel className="p-4 md:p-5">
                    <div className="flex items-center justify-between mb-4">
                      <h2 className="text-base font-bold">{t.myPlaylists}</h2>
                      <button
                        onClick={() => setNewPlaylistOpen(true)}
                        className="flex items-center gap-2 rounded-full bg-white/[0.08] px-4 py-2 text-[12.5px] font-semibold hover:bg-white/[0.14] transition-all"
                      >
                        <Plus className="size-4" />
                        Nueva
                      </button>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">
                      {playlists.map((pl) => (
                        <div
                          key={pl.id}
                          onClick={() => setSelectedPlaylistId(pl.id)}
                          className="group relative flex flex-col gap-3 rounded-2xl border border-white/[0.08] bg-white/[0.04] p-4 transition-all cursor-pointer hover:bg-white/[0.08] hover:border-[var(--cm-accent-edge)]"
                        >
                          <div className="flex items-center justify-between">
                            <div className="flex size-12 items-center justify-center rounded-xl bg-[var(--cm-accent-veil)]">
                              <ListMusic className="size-5 text-[var(--cm-accent-hi)]" />
                            </div>
                            <button
                              onClick={(e) => {
                                e.stopPropagation()
                                deletePlaylist(pl.id)
                              }}
                              className="opacity-0 group-hover:opacity-100 rounded-lg p-1.5 text-white/40 hover:text-rose-400 hover:bg-rose-400/10 transition-all"
                            >
                              <Trash2 className="size-3.5" />
                            </button>
                          </div>
                          <div>
                            <h3 className="truncate font-bold text-[13px]">{pl.name}</h3>
                            <p className="text-[11px] text-white/40 mt-0.5">{pl.tracks.length} canciones</p>
                          </div>
                          <div className="absolute bottom-3 right-3 opacity-0 group-hover:opacity-100 transition-opacity">
                            <div className="flex size-9 items-center justify-center rounded-full bg-[var(--cm-accent-hi)] text-[#08090b] shadow-lg shadow-[var(--cm-halo)]">
                              <Play className="size-4 fill-current ml-0.5" />
                            </div>
                          </div>
                        </div>
                      ))}
                      {playlists.length === 0 && (
                        <div className="col-span-full py-12 text-center">
                          <ListMusic className="mx-auto size-12 text-white/10 mb-3" />
                          <p className="text-sm text-white/40">{t.noPlaylistsYet}</p>
                          <button
                            onClick={() => setNewPlaylistOpen(true)}
                            className="mt-4 inline-flex items-center gap-2 rounded-full bg-[var(--cm-accent)] px-4 py-2.5 text-[13px] font-bold shadow-lg shadow-[var(--cm-halo)] hover:bg-[var(--cm-accent-hi)] transition-all"
                          >
                            <Plus className="size-4" />
                            {t.createPlaylist}
                          </button>
                        </div>
                      )}
                    </div>
                  </GlassPanel>
                )}

                {selectedPlaylistId && selectedPlaylistId !== 'favorites' && selectedPlaylistId !== 'history' && selectedPlaylist && (
                  <GlassPanel className="overflow-hidden p-0">
                    <div className="flex items-center justify-between px-4 pt-4 pb-2 md:px-5">
                      <div>
                        <h2 className="text-xl font-bold">{selectedPlaylist.name}</h2>
                        <p className="text-[12px] text-white/50 mt-0.5">
                          {selectedPlaylist.tracks.length} {t.playlistsCount}
                        </p>
                      </div>
                      {selectedPlaylist.tracks.length > 0 && (
                        <button
                          onClick={() => playTrack(selectedPlaylist.tracks[0], selectedPlaylist.tracks)}
                          className="flex items-center gap-2 rounded-full bg-[var(--cm-accent)] px-5 py-2.5 text-[13px] font-bold shadow-lg shadow-[var(--cm-halo)] hover:bg-[var(--cm-accent-hi)] transition-all"
                        >
                          <Play className="size-4 fill-current" />
                          {t.play}
                        </button>
                      )}
                    </div>
                    <div className="divide-y divide-white/[0.06]">
                      {selectedPlaylist.tracks.length > 0 ? (
                        selectedPlaylist.tracks.map((t, idx) => (
                          <TrackRow
                            key={`${t.id}-${idx}`}
                            track={t}
                            index={idx + 1}
                            queue={selectedPlaylist.tracks}
                            onSelectArtist={(a) => setSelectedArtistName(a)}
                            onSelectTrack={(tr) => setSelectedTrackDetail(tr)}
                          />
                        ))
                      ) : (
                        <div className="py-16 text-center">
                          <p className="text-sm text-white/40">{t.emptyPlaylist}</p>
                        </div>
                      )}
                    </div>
                  </GlassPanel>
                )}

                {selectedPlaylistId === 'favorites' && (
                  <GlassPanel className="overflow-hidden p-0">
                    <div className="flex items-center justify-between px-4 pt-4 pb-2 md:px-5">
                      <div>
                        <h2 className="text-xl font-bold flex items-center gap-2">
                          <Heart className="size-5 text-rose-400 fill-current" />
                          {t.myFavorites}
                        </h2>
                        <p className="text-[12px] text-white/50 mt-0.5">
                          {favorites.length} {t.savedSongs}
                        </p>
                      </div>
                      {favoriteTracks.length > 0 && (
                        <button
                          onClick={() => playTrack(favoriteTracks[0], favoriteTracks)}
                          className="flex items-center gap-2 rounded-full bg-[var(--cm-accent)] px-5 py-2.5 text-[13px] font-bold shadow-lg shadow-[var(--cm-halo)] hover:bg-[var(--cm-accent-hi)] transition-all"
                        >
                          <Play className="size-4 fill-current" />
                          {t.playAll}
                        </button>
                      )}
                    </div>
                    <div className="divide-y divide-white/[0.06]">
                      {favoriteTracks.length > 0 ? (
                        favoriteTracks.map((t, idx) => (
                          <TrackRow
                            key={t.id || idx}
                            track={t}
                            index={idx + 1}
                            queue={favoriteTracks}
                            onSelectArtist={(a) => setSelectedArtistName(a)}
                            onSelectTrack={(tr) => setSelectedTrackDetail(tr)}
                          />
                        ))
                      ) : (
                        <div className="py-16 text-center">
                          <Heart className="mx-auto size-12 text-white/10 mb-3" />
                          <p className="text-sm text-white/40">{t.noFavorites}</p>
                        </div>
                      )}
                    </div>
                  </GlassPanel>
                )}

                {selectedPlaylistId === 'history' && (
                  <GlassPanel className="overflow-hidden p-0">
                    <div className="flex items-center justify-between px-4 pt-4 pb-2 md:px-5">
                      <h2 className="text-xl font-bold flex items-center gap-2">
                        <Clock className="size-5 text-white/60" />
                        {t.listeningHistory}
                      </h2>
                      {history.length > 0 && (
                        <button onClick={clearHistory} className="text-[12px] font-semibold text-rose-400 hover:text-rose-300 transition-colors">
                          {t.clearHistory}
                        </button>
                      )}
                    </div>
                    <div className="divide-y divide-white/[0.06]">
                      {history.length > 0 ? (
                        history.map((entry, idx) => (
                          <TrackRow
                            key={`${entry.id}-${idx}`}
                            track={entry.track}
                            index={idx + 1}
                            queue={history.map((h) => h.track)}
                            onSelectArtist={(a) => setSelectedArtistName(a)}
                            onSelectTrack={(tr) => setSelectedTrackDetail(tr)}
                          />
                        ))
                      ) : (
                        <div className="py-16 text-center">
                          <Clock className="mx-auto size-12 text-white/10 mb-3" />
                          <p className="text-sm text-white/40">{t.noHistory}</p>
                        </div>
                      )}
                    </div>
                  </GlassPanel>
                )}
              </div>
            )}
          </main>
        </div>

        {/* Mobile bottom nav */}
        <nav className="lg:hidden fixed bottom-[76px] left-3 right-3 z-30 cm-glass-strong rounded-[20px] flex items-center justify-around px-2 py-2">
          <button onClick={() => setActiveTab('home')} aria-current={activeTab === 'home' ? 'page' : undefined} className={`flex flex-col items-center gap-0.5 px-4 py-1 rounded-xl transition-colors ${activeTab === 'home' ? 'text-[var(--cm-accent-hi)]' : 'text-white/40'}`}>
            <Home className="size-5" />
            <span className="text-[9px] font-semibold">{t.homeTab}</span>
          </button>
          <button onClick={() => setActiveTab('explore')} aria-current={activeTab === 'explore' ? 'page' : undefined} className={`flex flex-col items-center gap-0.5 px-4 py-1 rounded-xl transition-colors ${activeTab === 'explore' ? 'text-[var(--cm-accent-hi)]' : 'text-white/40'}`}>
            <Search className="size-5" />
            <span className="text-[9px] font-semibold">{t.exploreTab}</span>
          </button>
          <button onClick={() => setActiveTab('library')} aria-current={activeTab === 'library' ? 'page' : undefined} className={`flex flex-col items-center gap-0.5 px-4 py-1 rounded-xl transition-colors ${activeTab === 'library' ? 'text-[var(--cm-accent-hi)]' : 'text-white/40'}`}>
            <Library className="size-5" />
            <span className="text-[9px] font-semibold">{t.libraryTab}</span>
          </button>
        </nav>

      {/* Create Playlist Modal */}
      {newPlaylistOpen && (
        <div
          className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm"
          // Escape closes, and a click on the backdrop (not the panel) does too.
          onKeyDown={(e) => {
            if (e.key === 'Escape') setNewPlaylistOpen(false)
          }}
          onMouseDown={(e) => {
            if (e.target === e.currentTarget) setNewPlaylistOpen(false)
          }}
        >
          <form
            onSubmit={handleCreatePlaylist}
            className="w-full max-w-sm mx-4"
            role="dialog"
            aria-modal="true"
            aria-labelledby="cm-new-playlist-title"
          >
          <GlassPanel variant="strong" className="p-6 shadow-2xl space-y-4">
            <div className="flex items-center justify-between">
              <h3 id="cm-new-playlist-title" className="text-base font-bold">
                {t.newPlaylistModalTitle}
              </h3>
              <button type="button" onClick={() => setNewPlaylistOpen(false)} aria-label={t.close} className="rounded-xl p-1.5 text-white/50 hover:text-white hover:bg-white/10 transition-all">
                <X className="size-4" />
              </button>
            </div>
            <input
              type="text"
              placeholder={t.playlistName}
              aria-label={t.playlistName}
              value={newPlName}
              onChange={(e) => setNewPlName(e.target.value)}
              autoFocus
              className="cm-glass w-full rounded-2xl px-4 py-3 text-[13px] text-white placeholder:text-white/30 focus:outline-none focus:ring-2 focus:ring-[var(--cm-accent-edge)]"
            />
            <div className="flex justify-end gap-2 pt-2">
              <button type="button" onClick={() => setNewPlaylistOpen(false)} className="rounded-xl px-4 py-2.5 text-[12.5px] font-semibold text-white/50 hover:bg-white/5 transition-all">
                {t.cancel}
              </button>
              <button type="submit" className="rounded-xl bg-[var(--cm-accent)] px-5 py-2.5 text-[12.5px] font-bold shadow-lg shadow-[var(--cm-halo)] hover:bg-[var(--cm-accent-hi)] transition-all">
                {t.create}
              </button>
            </div>
          </GlassPanel>
          </form>
        </div>
      )}

      {/* Floating activity menu. Painted into its own layer outside the shell so
          it hovers over the whole view, pinned to the bell rather than to the
          header's box, and clamped so it never hangs off the window. */}
      {showNotifications && overlayHost && createPortal(
        <div
          className="cm-scope fixed inset-0 z-[220]"
          style={accentVars(accent)}
          onMouseDown={() => setShowNotifications(false)}
        >
          <GlassPanel
            variant="strong"
            role="dialog"
            aria-label={t.recentActivity}
            style={{
              top: notifAnchor?.top ?? 56,
              left: notifAnchor?.left,
              right: notifAnchor ? undefined : NOTIF_MENU_MARGIN,
              maxHeight: `calc(100dvh - ${(notifAnchor?.top ?? 56) + NOTIF_MENU_MARGIN}px)`,
            }}
            onMouseDown={(e) => e.stopPropagation()}
            className="fixed flex w-72 flex-col overflow-hidden p-3 shadow-2xl animate-in fade-in slide-in-from-top-2 duration-150"
          >
            <p className="text-[11px] font-bold uppercase tracking-wider text-white/40 mb-3">{t.recentActivity}</p>
            {history.length > 0 ? (
              <div className="min-h-0 flex-1 overflow-y-auto thin-scroll space-y-1 mb-3">
                {history.slice(0, 6).map((entry, idx) => (
                  <button
                    key={`${entry.id}-${idx}`}
                    onClick={() => {
                      playTrack(entry.track, history.map((h) => h.track))
                      setShowNotifications(false)
                    }}
                    className="flex w-full items-center gap-2 rounded-xl px-2 py-2 text-left hover:bg-white/5 transition-colors"
                  >
                    <div className="size-8 shrink-0 overflow-hidden rounded-lg">
                      <img src={entry.track.artworkUrl} alt="" className="size-full object-cover" />
                    </div>
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-[12px] font-semibold">{entry.track.title}</p>
                      <p className="truncate text-[10px] text-white/40">{entry.track.artist}</p>
                    </div>
                  </button>
                ))}
              </div>
            ) : (
              <p className="text-[12px] text-white/40 mb-3">{t.noHistory}</p>
            )}

            {notifPermission !== 'granted' && notifPermission !== 'unsupported' && (
              <button
                onClick={requestNotifications}
                className="cm-btn cm-btn-ghost w-full px-3 py-2 text-[12px]"
              >
                <Bell className="size-3.5" />
                {t.enableNotifications}
              </button>
            )}
            {notifPermission === 'denied' && (
              <p className="mt-2 flex items-center gap-1.5 text-[11px] text-rose-400/80">
                <BellOff className="size-3.5 shrink-0" />
                {t.notificationsBlocked}
              </p>
            )}
          </GlassPanel>
        </div>,
        overlayHost,
      )}
    </>
  )
}

'use client'

import React, { useEffect, useState } from 'react'
import { createPortal } from 'react-dom'
import {
  Heart,
  ListMusic,
  Pause,
  Play,
  Repeat,
  Repeat1,
  Shuffle,
  SkipBack,
  SkipForward,
  Volume2,
  VolumeX,
} from 'lucide-react'
import { useCatMusicPlayer } from '@/lib/plugins/cat-music/player-context'
import { useLibrary } from '@/lib/plugins/cat-music/library-context'
import { useAccentScopeStyle } from '@/lib/plugins/cat-music/accent-store'
import { formatDuration } from '@/lib/plugins/cat-music/youtube'
import { useLanguage } from '@/lib/i18n'
import { getFullscreenElement, subscribeFullscreenChange } from '@/lib/fullscreen'
import { QueuePanel } from './queue-panel'

export function CatMusicPlayerBar() {
  const player = useCatMusicPlayer()
  const library = useLibrary()
  const { t } = useLanguage()
  // Hooks must run before any early return, so they stay above the guards below.
  const [showQueue, setShowQueue] = useState(false)
  const [expanded, setExpanded] = useState(false)
  // The bar is a sibling of the plugin view, not a descendant, so it opens its
  // own accent scope instead of inheriting one. Each fixed layer below is a
  // separate root, so each one carries it.
  const accentScope = useAccentScopeStyle()

  /**
   * Promoting an element to fullscreen renders *only* that subtree, so a bar
   * sitting outside it disappears the moment the plugin view goes fullscreen.
   * Re-parenting it into whatever element is fullscreen keeps it on screen.
   */
  const [fullscreenHost, setFullscreenHost] = useState<Element | null>(null)
  useEffect(() => {
    const sync = () => setFullscreenHost(getFullscreenElement())
    sync()
    return subscribeFullscreenChange(sync)
  }, [])

  if (!player || !library) return null

  const {
    currentTrack,
    playerState,
    togglePlayPause,
    nextTrack,
    previousTrack,
    seekTo,
    setVolume,
    toggleMute,
    toggleShuffle,
    cycleRepeat,
  } = player

  const { isFavorite, toggleFavorite } = library

  if (!currentTrack) return null

  const fav = isFavorite(currentTrack.id)
  const isPlaying = playerState.isPlaying
  const pos = playerState.position || 0
  const dur = playerState.duration || 180
  const progressPct = Math.min(100, Math.max(0, (pos / dur) * 100))

  const bar = (
    <>
      {showQueue && (
        <div
          style={accentScope}
          className="cm-scope fixed right-4 bottom-24 z-50 animate-in fade-in slide-in-from-bottom-5 md:bottom-28"
        >
          <QueuePanel onClose={() => setShowQueue(false)} />
        </div>
      )}

      {expanded && (
        <div
          style={accentScope}
          className="cm-scope fixed inset-0 z-50 flex flex-col items-center justify-center bg-black/95 backdrop-blur-2xl md:hidden"
          onClick={() => setExpanded(false)}
        >
          <div className="size-64 overflow-hidden rounded-[28px] shadow-2xl ring-1 ring-white/10">
            <img
              src={currentTrack.artworkUrl}
              alt={currentTrack.title}
              className="size-full object-cover"
              onError={(e) => { (e.target as HTMLElement).setAttribute('src', '/placeholder.svg') }}
            />
          </div>
          <h2 className="mt-6 text-xl font-bold text-white text-center px-6">{currentTrack.title}</h2>
          <p className="mt-1 text-sm text-white/50">{currentTrack.artist}</p>
        </div>
      )}

      {/* Floating glass player bar. The 288px inset only clears the sidebar,
          which is itself hidden below `lg` — without the breakpoint the bar hung
          off the right edge on tablets and phones. In fullscreen the chat rail
          is gone, so it tucks in to the plugin's own sidebar instead. */}
      <div
        style={accentScope}
        className={`cm-scope fixed bottom-4 left-4 right-4 z-40 ${
          fullscreenHost ? 'lg:left-[248px]' : 'lg:left-[288px]'
        }`}
      >
        <div className="cm-glass-strong cm-player-float mx-auto max-w-[1600px] rounded-[24px] overflow-hidden">
          {playerState.error === 'unavailable' && (
            <div
              role="status"
              className="bg-rose-500/15 px-4 py-1.5 text-center text-[11px] font-medium text-rose-200"
            >
              {t.trackUnavailable}
            </div>
          )}

          {/* Progress bar on top edge */}
          <div className="relative h-1 bg-white/[0.06]">
            <div
              className="h-full bg-[var(--cm-accent)] transition-all duration-300"
              style={{ width: `${progressPct}%` }}
            />
            <input
              type="range"
              min={0}
              max={dur || 100}
              value={pos}
              onChange={(e) => seekTo(parseFloat(e.target.value))}
              aria-label={t.playerSeek}
              aria-valuetext={`${formatDuration(pos)} / ${formatDuration(dur)}`}
              className="absolute inset-0 size-full opacity-0 cursor-pointer"
            />
          </div>

          <div className="flex h-[68px] items-center gap-2 px-3 md:px-5">
            {/* Left: Track Info */}
            <div
              className="flex items-center gap-3 min-w-0 flex-1 md:w-1/4 cursor-pointer"
              onClick={() => setExpanded(!expanded)}
              role="button"
              tabIndex={0}
              aria-label={t.playerExpand}
              aria-expanded={expanded}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault()
                  setExpanded((v) => !v)
                }
              }}
            >
              <div className="relative size-12 shrink-0 overflow-hidden rounded-xl bg-white/5 shadow-md ring-1 ring-white/10">
                <img
                  src={currentTrack.artworkUrl}
                  alt={currentTrack.title}
                  className="size-full object-cover"
                  onError={(e) => { (e.target as HTMLElement).setAttribute('src', '/placeholder.svg') }}
                />
                {isPlaying && (
                  <div className="absolute inset-0 flex items-end justify-center bg-black/20 pb-1.5">
                    <span className="cm-eq h-3 text-[var(--cm-accent-hi)]" aria-hidden="true">
                      <i /><i /><i /><i />
                    </span>
                  </div>
                )}
              </div>
              <div className="min-w-0 flex-1 hidden sm:block">
                <p className="truncate text-[13px] font-bold text-white">{currentTrack.title}</p>
                <p className="truncate text-[11px] text-white/40">{currentTrack.artist}</p>
              </div>
              <button
                onClick={(e) => { e.stopPropagation(); toggleFavorite(currentTrack) }}
                aria-label={fav ? t.removeFavorite : t.addFavorite}
                aria-pressed={fav}
                className={`hidden sm:flex shrink-0 rounded-xl p-1.5 transition-colors ${
                  fav ? 'text-rose-400' : 'text-white/30 hover:text-white/70'
                }`}
              >
                <Heart className={`size-4 ${fav ? 'fill-current' : ''}`} />
              </button>
            </div>

            {/* Center: Playback Controls */}
            <div className="flex flex-col items-center gap-0.5 max-w-[600px] mx-auto flex-shrink md:flex-1">
              <div className="flex items-center gap-1 md:gap-3">
                <button
                  onClick={toggleShuffle}
                  aria-label={t.playerShuffle}
                  aria-pressed={playerState.shuffle}
                  className={`hidden sm:flex rounded-xl p-1.5 transition-colors ${
                    playerState.shuffle ? 'text-[var(--cm-accent-hi)]' : 'text-white/30 hover:text-white/60'
                  }`}
                >
                  <Shuffle className="size-[18px]" />
                </button>

                <button
                  onClick={previousTrack}
                  aria-label={t.playerPrevious}
                  className="rounded-xl p-1.5 text-white/50 hover:text-white transition-colors"
                >
                  <SkipBack className="size-[20px] fill-current" />
                </button>

                <button
                  onClick={togglePlayPause}
                  aria-label={isPlaying ? t.playerPause : t.playerPlay}
                  className="flex size-10 items-center justify-center rounded-full bg-white text-black shadow-lg transition-transform hover:scale-105 active:scale-95"
                >
                  {isPlaying ? (
                    <Pause className="size-[20px] fill-current" />
                  ) : (
                    <Play className="size-[20px] fill-current ml-0.5" />
                  )}
                </button>

                <button
                  onClick={nextTrack}
                  aria-label={t.playerNext}
                  className="rounded-xl p-1.5 text-white/50 hover:text-white transition-colors"
                >
                  <SkipForward className="size-[20px] fill-current" />
                </button>

                <button
                  onClick={cycleRepeat}
                  aria-label={
                    playerState.repeat === 'one'
                      ? t.playerRepeatOne
                      : playerState.repeat === 'all'
                        ? t.playerRepeatAll
                        : t.playerRepeat
                  }
                  aria-pressed={playerState.repeat !== 'off'}
                  className={`hidden sm:flex rounded-xl p-1.5 transition-colors ${
                    playerState.repeat !== 'off' ? 'text-[var(--cm-accent-hi)]' : 'text-white/30 hover:text-white/60'
                  }`}
                >
                  {playerState.repeat === 'one' ? <Repeat1 className="size-[17px]" /> : <Repeat className="size-[17px]" />}
                </button>
              </div>

              <div className="hidden md:flex w-full items-center gap-2 text-[10px] font-mono text-white/30 max-w-[500px]">
                <span className="w-9 text-right shrink-0">{formatDuration(pos)}</span>
                {/* Fixed-height rail so the scrubber can thicken on hover
                    without nudging the timestamps around it. */}
                <div className="flex h-3 flex-1 items-center">
                  <div className="cm-scrub w-full cursor-pointer">
                    <div className="cm-scrub-fill" style={{ width: `${progressPct}%` }} />
                    <div className="cm-scrub-knob" style={{ left: `${progressPct}%` }} />
                    <input
                      type="range"
                      min={0}
                      max={dur || 100}
                      value={pos}
                      onChange={(e) => seekTo(parseFloat(e.target.value))}
                      // Visual duplicate of the top-edge slider, which is present
                      // at every width. Exposing both would announce two
                      // identical seek controls.
                      aria-hidden="true"
                      tabIndex={-1}
                      className="absolute inset-0 size-full opacity-0 cursor-pointer"
                    />
                  </div>
                </div>
                <span className="w-9 shrink-0">{formatDuration(dur)}</span>
              </div>
            </div>

            {/* Right: Extra controls */}
            <div className="flex items-center justify-end gap-0.5 md:gap-1 flex-1 md:w-1/4">
              <button
                onClick={toggleMute}
                aria-label={playerState.muted ? t.playerUnmute : t.playerMute}
                aria-pressed={playerState.muted}
                className="hidden sm:flex rounded-xl p-1.5 text-white/30 hover:text-white/70 transition-colors"
              >
                {playerState.muted || playerState.volume === 0 ? (
                  <VolumeX className="size-[18px] text-rose-400" />
                ) : (
                  <Volume2 className="size-[18px]" />
                )}
              </button>
              <div className="hidden md:block w-20">
                <input
                  type="range"
                  min={0}
                  max={100}
                  value={playerState.muted ? 0 : playerState.volume}
                  onChange={(e) => setVolume(parseInt(e.target.value))}
                  aria-label={t.playerVolume}
                  aria-valuetext={`${playerState.muted ? 0 : playerState.volume}%`}
                  className="cm-range h-1 w-full cursor-pointer rounded-lg"
                />
              </div>

              <button
                onClick={() => setShowQueue((v) => !v)}
                aria-label={t.playerQueue}
                aria-pressed={showQueue}
                className={`rounded-xl p-1.5 transition-colors ${
                  showQueue ? 'text-[var(--cm-accent-hi)] bg-[var(--cm-accent-veil)]' : 'text-white/30 hover:text-white/70'
                }`}
              >
                <ListMusic className="size-[18px]" />
              </button>
            </div>
          </div>
        </div>
      </div>
    </>
  )

  return fullscreenHost ? createPortal(bar, fullscreenHost) : bar
}

'use client'

import React from 'react'
import { Trash2, X, Music, Volume2 } from 'lucide-react'
import { useCatMusicPlayer } from '@/lib/plugins/cat-music/player-context'
import { formatDuration } from '@/lib/plugins/cat-music/youtube'
import { useLanguage } from '@/lib/i18n'

export function QueuePanel({ onClose }: { onClose: () => void }) {
  const { currentTrack, playerState, removeFromQueue, clearQueue, playTrack } = useCatMusicPlayer()
  const { t } = useLanguage()

  const queue = playerState.queue
  const upcoming = queue.slice(playerState.index + 1)

  return (
    <div className="flex h-full w-80 flex-col rounded-3xl border border-white/[0.08] bg-[#15161a]/98 p-4 shadow-2xl backdrop-blur-2xl">
      <div className="flex items-center justify-between pb-3 border-b border-white/[0.06]">
        <div className="flex items-center gap-2">
          <Music className="size-4 text-[var(--cm-accent-hi)]" />
          <h3 className="text-sm font-bold text-white">{t.playerQueue}</h3>
        </div>
        <button
          onClick={onClose}
          aria-label={t.close}
          className="rounded-lg p-1 text-white/30 hover:bg-white/[0.08] hover:text-white transition-colors"
        >
          <X className="size-4" />
        </button>
      </div>

      <div className="thin-scroll flex-1 overflow-y-auto py-3 space-y-4">
        {currentTrack && (
          <div>
            <p className="mb-2 text-[10.5px] font-bold text-[var(--cm-accent-hi)] uppercase tracking-wider">{t.reproduciendo}</p>
            <div className="flex items-center gap-3 rounded-xl bg-[var(--cm-accent-veil)] p-2.5 border border-[var(--cm-accent-edge)]">
              <img
                src={currentTrack.artworkUrl}
                alt={currentTrack.title}
                className="size-10 rounded-lg object-cover"
                onError={(e) => { (e.target as HTMLElement).setAttribute('src', '/placeholder.svg') }}
              />
              <div className="min-w-0 flex-1">
                <p className="truncate text-[12.5px] font-bold text-[var(--cm-accent-hi)]">{currentTrack.title}</p>
                <p className="truncate text-[11px] text-white/40">{currentTrack.artist}</p>
              </div>
              <Volume2 className="size-4 text-[var(--cm-accent-hi)] animate-pulse shrink-0" />
            </div>
          </div>
        )}

        <div>
          <div className="flex items-center justify-between mb-2">
            <p className="text-[10.5px] font-bold text-white/30 uppercase tracking-wider">
              {t.upNext} ({upcoming.length})
            </p>
            {upcoming.length > 0 && (
              <button
                onClick={clearQueue}
                className="text-[11px] font-semibold text-rose-400 hover:underline"
              >
                {t.clear}
              </button>
            )}
          </div>

          {upcoming.length > 0 ? (
            <div className="space-y-1">
              {upcoming.map((track, idx) => {
                const actualIndex = playerState.index + 1 + idx
                return (
                  <div
                    key={`${track.id}-${idx}`}
                    className="group flex items-center justify-between gap-2 rounded-xl p-2 text-[12px] hover:bg-white/[0.04] transition-colors cursor-pointer"
                    onClick={() => playTrack(track)}
                  >
                    <img
                      src={track.artworkUrl}
                      alt={track.title}
                      className="size-8 rounded-lg object-cover shrink-0"
                      onError={(e) => { (e.target as HTMLElement).setAttribute('src', '/placeholder.svg') }}
                    />
                    <div className="min-w-0 flex-1">
                      <p className="truncate font-semibold text-white">{track.title}</p>
                      <p className="truncate text-[10.5px] text-white/40">{track.artist}</p>
                    </div>
                    <span className="text-[10.5px] font-mono text-white/30 shrink-0">
                      {formatDuration(track.durationSeconds)}
                    </span>
                    <button
                      onClick={(e) => {
                        e.stopPropagation()
                        removeFromQueue(actualIndex)
                      }}
                      aria-label={t.removeFromQueue}
                      className="opacity-0 group-hover:opacity-100 p-1 text-white/30 hover:text-rose-400 transition-opacity"
                    >
                      <Trash2 className="size-3.5" />
                    </button>
                  </div>
                )
              })}
            </div>
          ) : (
            <p className="py-6 text-center text-[12px] text-white/30">{t.queueEmpty}</p>
          )}
        </div>
      </div>
    </div>
  )
}

'use client'

import React from 'react'
import { Heart, Play, Pause } from 'lucide-react'
import type { Track } from '@/lib/plugins/cat-music/types'
import { useCatMusicPlayer } from '@/lib/plugins/cat-music/player-context'
import { useLibrary } from '@/lib/plugins/cat-music/library-context'
import { useLanguage } from '@/lib/i18n'

export function TrackCard({ track, queue }: { track: Track; queue?: Track[] }) {
  const { currentTrack, playerState, playTrack, togglePlayPause } = useCatMusicPlayer()
  const { isFavorite, toggleFavorite } = useLibrary()
  const { t } = useLanguage()

  const isCurrent = currentTrack?.id === track.id
  const isPlaying = isCurrent && playerState.isPlaying
  const fav = isFavorite(track.id)

  const handlePlay = () => {
    if (isCurrent) {
      togglePlayPause()
    } else {
      playTrack(track, queue)
    }
  }

  return (
    <div className="group relative flex flex-col gap-0.5 rounded-[10px] p-0 transition-colors hover:bg-white/[0.04]">
      <div className="relative aspect-square w-full overflow-hidden rounded-[10px] bg-white/[0.04]">
        <img
          src={track.artworkUrl}
          alt={track.title}
          className="size-full object-cover transition-transform duration-500 group-hover:scale-105"
          onError={(e) => { (e.target as HTMLElement).setAttribute('src', '/placeholder.svg') }}
        />

        <button
          onClick={handlePlay}
          aria-label={isPlaying ? t.playerPause : t.playerPlay}
          className={`absolute right-1 bottom-1 flex size-6 items-center justify-center rounded-full bg-[var(--cm-accent-hi)] text-[#08090b] shadow-lg shadow-[var(--cm-halo)] transition-all ${
            isCurrent ? 'scale-100 opacity-100' : 'translate-y-2 opacity-0 group-hover:translate-y-0 group-hover:opacity-100'
          } hover:scale-110 active:scale-95`}
        >
          {isPlaying ? <Pause className="size-3.5 fill-current" /> : <Play className="size-3.5 fill-current ml-0.5" />}
        </button>

        {isCurrent && isPlaying && (
          <div className="absolute inset-0 flex items-end justify-center gap-0.5 p-1 bg-black/25">
            <span className="w-0.5 bg-[var(--cm-accent)] rounded-full h-1.5 animate-pulse" />
            <span className="w-0.5 bg-[var(--cm-accent)] rounded-full h-2 animate-pulse delay-75" />
            <span className="w-0.5 bg-[var(--cm-accent)] rounded-full h-1 animate-pulse delay-150" />
          </div>
        )}

        <button
          onClick={(e) => { e.stopPropagation(); toggleFavorite(track) }}
          aria-label={fav ? t.removeFavorite : t.addFavorite}
          className={`absolute left-1 top-1 flex size-5 items-center justify-center rounded-full bg-black/50 backdrop-blur-md transition-all ${
            fav ? 'opacity-100 text-rose-400' : 'opacity-0 group-hover:opacity-100 text-white/70 hover:text-rose-300'
          }`}
        >
          <Heart className={`size-3 ${fav ? 'fill-current' : ''}`} />
        </button>
      </div>

      <div className="min-w-0 px-0">
        <h4 className={`truncate text-[11px] font-semibold leading-tight ${isCurrent ? 'text-[var(--cm-accent-hi)]' : 'text-white'}`}>
          {track.title}
        </h4>
        <p className="truncate text-[10px] text-white/40 leading-tight">{track.artist}</p>
      </div>
    </div>
  )
}

'use client'

import React, { useState } from 'react'
import {
  ArrowLeft,
  Heart,
  Pause,
  Play,
  Plus,
  Radio,
  ListMusic,
  Sparkles,
  Clock,
} from 'lucide-react'
import type { Track } from '@/lib/plugins/cat-music/types'
import { useCatMusicPlayer } from '@/lib/plugins/cat-music/player-context'
import { useLibrary } from '@/lib/plugins/cat-music/library-context'
import { formatDuration } from '@/lib/plugins/cat-music/youtube'
import { SEED_TRACKS } from '@/lib/plugins/cat-music/catalog'
import { useLanguage } from '@/lib/i18n'
import { TrackRow } from './track-row'

export function TrackDetailView({
  track,
  onBack,
  onSelectArtist,
}: {
  track: Track
  onBack: () => void
  onSelectArtist: (artistName: string) => void
}) {
  const { currentTrack, playerState, playTrack, togglePlayPause } = useCatMusicPlayer()
  const { isFavorite, toggleFavorite, playlists, addTrackToPlaylist } = useLibrary()
  const { t } = useLanguage()

  const [playlistMenuOpen, setPlaylistMenuOpen] = useState(false)
  const isCurrent = currentTrack?.id === track.id
  const isPlaying = isCurrent && playerState.isPlaying
  const fav = isFavorite(track.id)

  const relatedTracks = SEED_TRACKS.filter(
    (candidate) =>
      candidate.id !== track.id &&
      (candidate.artist === track.artist || candidate.genre === track.genre),
  ).slice(0, 5)

  return (
    <div className="flex h-full w-full flex-col overflow-y-auto thin-scroll text-white">
      {/* Hero Section with Header */}
      <div className="relative px-4 pt-4 md:px-8 md:pt-6 pb-8">
        {/* Gradient glow behind artwork */}
        <div className="absolute top-1/4 left-1/2 -translate-x-1/2 w-96 h-96 bg-[var(--cm-accent-veil)] rounded-full blur-3xl pointer-events-none" />

        <div className="relative z-10">
          {/* Back Button */}
          <button
            onClick={onBack}
            aria-label={t.back}
            className="inline-flex items-center gap-2 rounded-xl bg-white/[0.06] px-4 py-2 text-[13px] font-semibold text-white/70 hover:bg-white/[0.12] hover:text-white transition-all mb-6"
          >
            <ArrowLeft className="size-4" />
            <span>{t.back}</span>
          </button>

          <div className="flex flex-col md:flex-row items-center gap-8">
            {/* Large Artwork. The rotating conic ring lives on a wrapper because
                the artwork itself clips, and the mirrored copy underneath sits
                the cover on a surface instead of floating it in the dark. */}
            <div className="shrink-0">
              <div className="cm-halo-ring cm-glow rounded-3xl">
                <div className="relative size-56 md:size-64 overflow-hidden rounded-3xl shadow-2xl ring-1 ring-white/[0.06]">
                  <img
                    src={track.artworkUrl}
                    alt={track.title}
                    className="size-full object-cover"
                    onError={(e) => { (e.target as HTMLElement).setAttribute('src', '/placeholder.svg') }}
                  />
                  {isPlaying && (
                    <div className="absolute inset-0 flex items-center justify-center bg-black/45 backdrop-blur-[2px]">
                      <span className="cm-eq h-10 w-10 gap-1" aria-hidden="true">
                        <i /><i /><i /><i />
                      </span>
                    </div>
                  )}
                </div>
              </div>
              <div className="cm-reflect mt-1 h-16 overflow-hidden rounded-3xl" aria-hidden="true">
                <img
                  src={track.artworkUrl}
                  alt=""
                  className="size-full object-cover object-bottom"
                  onError={(e) => { (e.target as HTMLElement).setAttribute('src', '/placeholder.svg') }}
                />
              </div>
            </div>

            {/* Info */}
            <div className="flex-1 space-y-4 text-center md:text-left">
              <div className="flex flex-wrap items-center justify-center md:justify-start gap-2">
                <span className="rounded-full bg-[var(--cm-accent-veil)] px-3 py-0.5 text-[11px] font-bold text-[var(--cm-accent-hi)]">
                  {track.genre || t.song}
                </span>
                {track.year && (
                  <span className="rounded-full bg-white/[0.06] px-3 py-0.5 text-[11px] text-white/40">
                    {track.year}
                  </span>
                )}
                <span className="rounded-full bg-white/[0.06] px-3 py-0.5 text-[11px] text-white/40 flex items-center gap-1">
                  <Clock className="size-3" />
                  {formatDuration(track.durationSeconds)}
                </span>
              </div>

              <h1 className="text-3xl md:text-4xl font-black tracking-tight text-white">{track.title}</h1>

              <button
                onClick={() => onSelectArtist(track.artist)}
                className="cm-title-link cm-focus group inline-flex items-center gap-2 rounded-full text-base font-semibold text-white/50"
              >
                <div className="size-8 rounded-full bg-white/[0.06] flex items-center justify-center overflow-hidden">
                  <Radio className="size-4 group-hover:text-[var(--cm-accent-hi)] transition-colors" />
                </div>
                <span className="group-hover:underline">{track.artist}</span>
              </button>

              {track.album && (
                <p className="text-sm text-white/30">
                  {t.albumLabel}: <span className="text-white/60 font-medium">{track.album}</span>
                </p>
              )}

              {/* Action Buttons */}
              <div className="flex flex-wrap items-center justify-center md:justify-start gap-3 pt-2">
                <button
                  onClick={() => (isCurrent ? togglePlayPause() : playTrack(track))}
                  className="cm-btn cm-btn-primary cm-focus px-6 py-3 text-sm"
                >
                  {isPlaying ? <Pause className="size-5 fill-current" /> : <Play className="size-5 fill-current" />}
                  <span>{isPlaying ? t.playerPause : t.playerPlay}</span>
                </button>

                <button
                  onClick={() => toggleFavorite(track)}
                  aria-pressed={fav}
                  className={`cm-btn cm-focus px-5 py-3 text-sm ${
                    fav
                      ? 'border border-rose-500/30 bg-rose-500/10 text-rose-400'
                      : 'cm-btn-ghost'
                  }`}
                >
                  <Heart className={`size-4.5 ${fav ? 'fill-current' : ''}`} />
                  <span>{fav ? t.inFavorites : t.save}</span>
                </button>

                {/* Add to Playlist */}
                <div className="relative">
                  <button
                    onClick={() => setPlaylistMenuOpen((v) => !v)}
                    aria-expanded={playlistMenuOpen}
                    className="cm-btn cm-btn-ghost cm-focus px-5 py-3 text-sm"
                  >
                    <Plus className="size-4.5" />
                    <span>{t.playlist}</span>
                  </button>
                  {playlistMenuOpen && (
                    <>
                      <div className="fixed inset-0 z-40" onClick={() => setPlaylistMenuOpen(false)} />
                      <div className="absolute left-0 bottom-full mb-2 z-50 w-56 rounded-2xl border border-white/[0.08] bg-[#1a1b1e] p-2 shadow-2xl">
                        <div className="px-2.5 py-1.5 text-[10px] font-bold text-white/30 uppercase tracking-wider">
                          {t.addToPlaylist}
                        </div>
                        {playlists.length > 0 ? (
                          playlists.map((pl) => (
                            <button key={pl.id}
                              onClick={() => { addTrackToPlaylist(pl.id, track); setPlaylistMenuOpen(false) }}
                              className="flex w-full items-center gap-2 rounded-xl px-2.5 py-2 text-[12px] text-white/70 hover:bg-white/[0.08] hover:text-white transition-colors">
                              <ListMusic className="size-3.5" />
                              <span className="truncate">{pl.name}</span>
                            </button>
                          ))
                        ) : (
                          <div className="px-2.5 py-2 text-[11px] text-white/30">{t.noPlaylistsYet}</div>
                        )}
                      </div>
                    </>
                  )}
                </div>

              </div>

            </div>
          </div>
        </div>
      </div>

      {/* Related Tracks */}
      {relatedTracks.length > 0 && (
        <div className="px-4 md:px-8 pb-8 space-y-3">
          <div className="flex items-center gap-2">
            <Sparkles className="size-4 text-[var(--cm-accent-hi)]" />
            <h3 className="text-base font-bold text-white">
              {t.similarSongsBy} {track.artist}
            </h3>
          </div>
          <div className="cm-acrylic rounded-2xl divide-y divide-white/[0.04]">
            {relatedTracks.map((related, idx) => (
              <TrackRow
                key={related.id}
                track={related}
                index={idx + 1}
                queue={relatedTracks}
                onSelectArtist={onSelectArtist}
              />
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

'use client'

import React, { useState, useRef, useEffect } from 'react'
import { Heart, MoreHorizontal, Play, Info, Radio, ListMusic } from 'lucide-react'
import type { Track } from '@/lib/plugins/cat-music/types'
import { useCatMusicPlayer } from '@/lib/plugins/cat-music/player-context'
import { useLibrary } from '@/lib/plugins/cat-music/library-context'
import { formatDuration } from '@/lib/plugins/cat-music/youtube'
import { useLanguage } from '@/lib/i18n'

export function TrackRow({
  track,
  index,
  queue,
  onSelectArtist,
  onSelectTrack,
  showIndex,
}: {
  track: Track
  index?: number
  queue?: Track[]
  onSelectArtist?: (artistName: string) => void
  onSelectTrack?: (track: Track) => void
  showIndex?: boolean
}) {
  const { currentTrack, playerState, playTrack, togglePlayPause } = useCatMusicPlayer()
  const { isFavorite, toggleFavorite, playlists, addTrackToPlaylist } = useLibrary()
  const { t } = useLanguage()
  const [showMenu, setShowMenu] = useState(false)

  const isCurrent = currentTrack?.id === track.id
  const isPlaying = isCurrent && playerState.isPlaying
  const fav = isFavorite(track.id)

  const titleRef = useRef<HTMLButtonElement>(null)
  const artistRef = useRef<HTMLButtonElement>(null)
  const [titleOverflows, setTitleOverflows] = useState(false)
  const [artistOverflows, setArtistOverflows] = useState(false)
  const [titleMarquee, setTitleMarquee] = useState('')
  const [artistMarquee, setArtistMarquee] = useState('')

  useEffect(() => {
    if (titleRef.current) {
      const el = titleRef.current
      const overflow = el.scrollWidth - el.clientWidth
      if (overflow > 0) {
        setTitleOverflows(true)
        setTitleMarquee(`-${overflow}px`)
      } else {
        setTitleOverflows(false)
      }
    }
    if (artistRef.current) {
      const el = artistRef.current
      const overflow = el.scrollWidth - el.clientWidth
      if (overflow > 0) {
        setArtistOverflows(true)
        setArtistMarquee(`-${overflow}px`)
      } else {
        setArtistOverflows(false)
      }
    }
  }, [track.title, track.artist])

  const handlePlayClick = () => {
    if (isCurrent) { togglePlayPause() } else { playTrack(track, queue) }
  }

  return (
    <div
      className={`group relative flex items-center gap-3 px-4 py-2.5 text-[13px] transition-all rounded-lg ${
        isCurrent ? 'bg-[var(--cm-accent-veil)]' : 'hover:bg-white/[0.04]'
      }`}
    >
      <div className="flex items-center gap-3 min-w-0 flex-1">
        <div className="relative flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-xl bg-white/[0.04] ring-1 ring-white/[0.06]">
          {showIndex && !isCurrent && (
            <span className="text-[11px] font-semibold text-white/30 tabular-nums">{index}</span>
          )}
          <img
            src={track.artworkUrl}
            alt={track.title}
            className={`size-10 rounded-xl object-cover ${showIndex && !isCurrent ? 'group-hover:opacity-0' : ''}`}
            onError={(e) => { (e.target as HTMLElement).setAttribute('src', '/placeholder.svg') }}
          />
          <button
            onClick={handlePlayClick}
            aria-label={isPlaying ? t.playerPause : t.playerPlay}
            className={`absolute inset-0 flex items-center justify-center bg-black/60 text-white transition-opacity ${
              isCurrent ? 'opacity-100' : 'opacity-0 group-hover:opacity-100'
            }`}
          >
            {isPlaying ? (
              <span className="flex items-end gap-0.5 h-3">
                <span className="w-0.5 bg-[var(--cm-accent)] animate-pulse h-3 rounded-full" />
                <span className="w-0.5 bg-[var(--cm-accent)] animate-pulse h-2 delay-75 rounded-full" />
                <span className="w-0.5 bg-[var(--cm-accent)] animate-pulse h-3.5 delay-150 rounded-full" />
              </span>
            ) : (
              <Play className="size-4 fill-current ml-0.5" />
            )}
          </button>
        </div>

        <div className="min-w-0 flex-1">
          <button
            ref={titleRef}
            onClick={() => onSelectTrack?.(track)}
            className={`block text-left max-w-full font-semibold hover:underline ${titleOverflows ? 'marquee-container' : 'truncate'} ${isCurrent ? 'text-[var(--cm-accent-hi)]' : 'text-white'}`}
          >
