          const isForwarded = unpinConfirmMsg.content.startsWith('[Mensaje reenviado]:\n')
          const displayContent = isForwarded
            ? unpinConfirmMsg.content.slice('[Mensaje reenviado]:\n'.length)
            : unpinConfirmMsg.content

          return (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/75 backdrop-blur-sm p-4">
              <motion.div
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                transition={{ duration: 0.15 }}
                className="w-full max-w-110 rounded-lg bg-popover text-popover-foreground p-4 shadow-2xl relative border border-border/20"
                onClick={(e) => e.stopPropagation()}
              >
                {/* Close X Button */}
                <button
                  onClick={() => setUnpinConfirmMsg(null)}
                  className="absolute top-4 right-4 text-muted-foreground hover:text-foreground transition-colors p-1"
                >
                  <X className="size-5" />
                </button>

                {/* Header */}
                <h3 className="text-[20px] font-bold text-foreground leading-tight mb-1 pr-6">
                  {lang === 'es' ? 'Retirar mensaje' : 'Unpin Message'}
                </h3>
                <p className="text-[13.5px] text-muted-foreground leading-normal mb-4">
                  {lang === 'es' ? '¿Seguro que quieres eliminar este mensaje fijado?' : 'Are you sure you want to unpin this message?'}
                </p>

                {/* Message Preview Container */}
                <div className="bg-secondary/30 rounded-md p-4 mb-5 border border-border/40 flex gap-3 items-start shadow-inner select-text">
                  <span className="flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-full bg-secondary text-[12px] font-semibold text-muted-foreground mt-0.5">
                    {unpinConfirmMsg.senderImage ? (
                      <img src={unpinConfirmMsg.senderImage} alt="" className="size-10 rounded-full object-cover" />
                    ) : (
                      initialsOf(unpinConfirmMsg.senderName)
                    )}
                  </span>
                  <div className="min-w-0 flex-1">
                    <div className="flex items-baseline gap-2">
                      <span className="text-[13.5px] font-semibold text-foreground/90">{unpinConfirmMsg.senderName}</span>
                      <span className="text-[11px] text-muted-foreground">{formatTime(unpinConfirmMsg.createdAt)}</span>
                    </div>
                    {isForwarded ? (
                      <div className="flex gap-2 mt-1">
                        <div className="w-[2.5px] bg-[#4e5058] rounded-full shrink-0 my-0.5" />
                        <div className="flex flex-col gap-0.5 min-w-0">
                          <div className="flex items-center gap-1 text-[10px] text-muted-foreground font-medium italic select-none">
                            <Forward className="size-3 shrink-0" />
                            <span>{lang === 'es' ? 'Reenviado' : 'Forwarded'}</span>
                          </div>
                          <p className="mt-0.5 text-[13px] text-foreground/90 whitespace-pre-wrap leading-relaxed">{displayContent}</p>
                        </div>
                      </div>
                    ) : (
                      <p className="mt-0.5 text-[13px] text-foreground/90 whitespace-pre-wrap leading-relaxed">{unpinConfirmMsg.content}</p>
                    )}
                  </div>
                </div>

                {/* Buttons Footer */}
                <div className="flex items-center justify-end gap-3 bg-secondary/30 -mx-4 -mb-4 p-4 rounded-b-lg border-t border-border/50">
                  <button
                    onClick={() => setUnpinConfirmMsg(null)}
                    className="px-5 py-2 text-muted-foreground hover:text-foreground hover:underline text-[13px] font-medium transition-colors select-none"
                  >
                    {t.cancelBtn}
                  </button>
                  <button
                    onClick={() => {
                      handleTogglePin(unpinConfirmMsg.id)
                      setUnpinConfirmMsg(null)
                    }}
                    className="px-6 py-2 bg-[#f23f43] hover:bg-[#da373c] active:bg-[#a92b2f] text-white text-[13.5px] font-semibold rounded-[4px] transition-colors shadow-sm select-none"
                  >
                    {lang === 'es' ? '¡Elimínalo!' : 'Remove it!'}
                  </button>
                </div>
              </motion.div>
            </div>
          )
        })()}
      </AnimatePresence>

      {conversation && (
        <AddMembersModal
          open={addMembersOpen}
          onClose={() => setAddMembersOpen(false)}
          conversationId={conversation.id}
          onMembersAdded={() => {
            onConversationInfoChange?.(conversation.id)
          }}
        />
      )}

      {/* User popover */}
      {popoverUser && popoverAnchor && (() => {
        const isOnline = popoverUser.id === user.id || Array.from(onlineUserIds).some((id) => String(id) === String(popoverUser.id))
        return (
          <UserPopover
            user={{
              ...popoverUser,
              isOnline,
            }}
            currentUserId={user.id}
            anchorRect={popoverAnchor}
            onClose={() => { setPopoverUser(null); setPopoverAnchor(null) }}
            onOpenFullProfile={() => {
              setProfileModalUser({
                ...popoverUser,
                isOnline,
              })
              setPopoverUser(null)
              setPopoverAnchor(null)
            }}
          />
        )
      })()}

      {/* Full profile modal */}
      {profileModalUser && (
        <UserProfileModal
          user={profileModalUser}
          currentUserId={user.id}
          onClose={() => setProfileModalUser(null)}
        />
      )}

    </section>
  )
}

'use client'

import { Check, X } from 'lucide-react'
import { useState } from 'react'
import useSWR, { mutate as globalMutate } from 'swr'
import { getPendingRequests, acceptFriendRequest, rejectFriendRequest, type FriendRequestWithUser } from '@/app/actions/friends'
import { createDirectConversation } from '@/app/actions/chat'

function initialsOf(name: string) {
  return name
    .split(' ')
    .map((p) => p[0])
    .slice(0, 2)
    .join('')
    .toUpperCase()
}

export function FriendRequestsPanel({
  currentUserId,
  onChatWithUser,
}: {
  currentUserId: string
  onChatWithUser?: (id: number) => void
}) {
  const { data: requests = [], mutate } = useSWR(
    'friend-requests',
    getPendingRequests,
    { refreshInterval: 5000, revalidateOnFocus: true },
  )

  const [acting, setActing] = useState<string | null>(null)

  const incoming = requests.filter((r) => r.status === 'pending' && r.toUserId === currentUserId)

  const handleAccept = async (req: FriendRequestWithUser) => {
    if (acting) return
    setActing(req.id)
    try {
      await acceptFriendRequest(req.id)
      const { id } = await createDirectConversation(req.fromUserId)
      globalMutate('conversations')
      onChatWithUser?.(id)
    } finally {
      setActing(null)
      mutate()
    }
  }

  const handleReject = async (reqId: string) => {
    if (acting) return
    setActing(reqId)
    try {
      await rejectFriendRequest(reqId)
    } finally {
      setActing(null)
      mutate()
    }
  }

  if (incoming.length === 0) return null

  return (
    <div className="mt-3">
      <p className="px-2 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground/70">
        Pending Requests
      </p>
      <div className="mt-1 space-y-0.5">
        {incoming.map((req) => (
          <div
            key={req.id}
            className="group flex items-center gap-2 rounded-lg px-2 py-1.5 transition-colors hover:bg-secondary/70"
          >
            <span className="flex size-7 shrink-0 items-center justify-center overflow-hidden rounded-full bg-secondary text-[10px] font-semibold text-muted-foreground">
              {req.fromUser.image ? (
                <img
                  src={req.fromUser.image}
                  alt=""
                  className="size-7 rounded-full object-cover"
                />
              ) : (
                initialsOf(req.fromUser.name)
              )}
            </span>
            <span className="min-w-0 flex-1 truncate text-[13px] font-medium">
              {req.fromUser.name}
            </span>
            <button
              onClick={() => handleAccept(req)}
              disabled={acting !== null}
              className="rounded-md p-1 text-green-500 opacity-0 transition-all hover:bg-green-500/10 group-hover:opacity-100"
              title="Accept"
            >
              <Check className="size-3.5" />
            </button>
            <button
              onClick={() => handleReject(req.id)}
              disabled={acting !== null}
              className="rounded-md p-1 text-red-500 opacity-0 transition-all hover:bg-red-500/10 group-hover:opacity-100"
              title="Reject"
            >
              <X className="size-3.5" />
            </button>
          </div>
        ))}
      </div>
    </div>
  )
}

'use client'

import React, { useState } from 'react'
import { useLanguage } from '@/lib/i18n'
import { usePlugins } from '@/lib/plugins/plugin-provider'

function pluginIconSrc(id: string) {
  if (id === 'cat-music') return '/catmusic.png'
  return `/plugins/${id}/icon.png`
}

function PluginRailIcon({
  id,
  label,
  fallback,
}: {
  id: string
  label: string
  fallback: React.ReactNode
}) {
  const [imgFailed, setImgFailed] = useState(false)

  if (imgFailed) {
    return (
      <span className="flex h-full w-full items-center justify-center text-foreground">
        {fallback}
      </span>
    )
  }

  return (
    <img
      src={pluginIconSrc(id)}
      alt={label}
      className="h-full w-full object-cover"
      onError={() => setImgFailed(true)}
    />
  )
}

export function IconRail({
  activeView,
  onSelectView,
}: {
  activeView?: string
  onSelectView?: (viewId: string) => void
}) {
  const { t } = useLanguage()
  const { getActiveRailTabs } = usePlugins()

  const pluginTabs = getActiveRailTabs()

  return (
    <aside
      aria-label={t.workspacesLabel}
      className="flex h-full w-20 shrink-0 flex-col items-center gap-3 pt-1 pb-4 select-none"
    >
      <button
        aria-label={t.catChatWorkspaceLabel}
        onClick={() => onSelectView?.('chat')}
        className={`flex size-20 shrink-0 items-center justify-center overflow-hidden rounded-xl transition-all ${
          !activeView || activeView === 'chat'
            ? 'scale-105 opacity-100'
            : 'opacity-70 hover:opacity-100 hover:scale-105'
        }`}
      >
        <img src="/cat-chat-logo.png" alt="CatChat Logo" className="h-full w-full object-contain" />
      </button>

      <div className="my-1 h-px w-6 bg-border/40" />

      {pluginTabs.map((tab) => {
        const isSelected = activeView === tab.id
        return (
          <button
            key={tab.id}
            onClick={() => onSelectView?.(tab.id)}
            title={tab.label}
