let mainWindow
let splashWindow
let nextServer
let pendingDisplayMediaCallback = null
let pendingScreenSources = []

function setupAutoUpdater() {
  autoUpdater.autoDownload = false
  autoUpdater.autoInstallOnAppQuit = false

  autoUpdater.setFeedURL({
    provider: 'generic',
    url: 'https://catchat-three.vercel.app/updates/',
  })

  ipcMain.handle('update:check', async () => {
    try {
      const result = await autoUpdater.checkForUpdates()
      return result?.updateInfo || null
    } catch (err) {
      console.error('[AutoUpdater] Check failed:', err.message)
      return null
    }
  })

  ipcMain.handle('update:download', async () => {
    try {
      await autoUpdater.downloadUpdate()
    } catch (err) {
      console.error('[AutoUpdater] Download failed:', err.message)
      throw err
    }
  })

  ipcMain.handle('update:install', () => {
    autoUpdater.quitAndInstall()
  })

  ipcMain.handle('app:version', () => app.getVersion())

  autoUpdater.on('update-available', (info) => {
    mainWindow?.webContents.send('update:available', info)
  })

  autoUpdater.on('download-progress', (progress) => {
    mainWindow?.webContents.send('update:download-progress', progress)
  })

  autoUpdater.on('update-downloaded', (info) => {
    mainWindow?.webContents.send('update:downloaded', info)
  })

  autoUpdater.on('error', (error) => {
    const msg = error?.message || ''
    if (msg.includes('No published versions') || msg.includes('404') || msg.includes('ENOENT')) {
      console.log('[AutoUpdater] No updates available')
      return
    }
    mainWindow?.webContents.send('update:error', error.message)
  })
}

/**
 * The window controls the renderer is allowed to drive. Registered once at
 * startup and resolved through `fromWebContents`, so it survives windows being
 * closed and recreated (`app.on('activate')`).
 */
function registerWindowIPC() {
  ipcMain.handle('window:set-fullscreen', (event, flag) => {
    const win = BrowserWindow.fromWebContents(event.sender)
    if (!win || win.isDestroyed()) return false
    win.setFullScreen(Boolean(flag))
    return win.isFullScreen()
  })

  ipcMain.handle('window:is-fullscreen', (event) => {
    const win = BrowserWindow.fromWebContents(event.sender)
    return Boolean(win && !win.isDestroyed() && win.isFullScreen())
  })

  // The frame is drawn by the renderer (see components/window-titlebar.tsx), so
  // the buttons it paints need the real window operations behind them.
  ipcMain.handle('window:minimize', (event) => {
    const win = BrowserWindow.fromWebContents(event.sender)
    if (win && !win.isDestroyed()) win.minimize()
  })

  ipcMain.handle('window:toggle-maximize', (event) => {
    const win = BrowserWindow.fromWebContents(event.sender)
    if (!win || win.isDestroyed()) return false
    if (win.isMaximized()) win.unmaximize()
    else win.maximize()
    return win.isMaximized()
  })

  ipcMain.handle('window:is-maximized', (event) => {
    const win = BrowserWindow.fromWebContents(event.sender)
    return Boolean(win && !win.isDestroyed() && win.isMaximized())
  })

  ipcMain.handle('window:close', (event) => {
    const win = BrowserWindow.fromWebContents(event.sender)
    if (win && !win.isDestroyed()) win.close()
  })
}

function getAppDir() {
  if (app.isPackaged) {
    return app.getAppPath()
  }

  return __dirname
}

function createSplashWindow() {
  const appDir = getAppDir()

  splashWindow = new BrowserWindow({
    width: 320,
    height: 350,
    frame: false, // Sin bordes de Windows
    resizable: false,
    alwaysOnTop: true,
    transparent: false,
    backgroundColor: '#0a0a0a',
    icon: path.join(appDir, 'build', 'icon.png'),
    webPreferences: {
      nodeIntegration: false,
      contextIsolation: true
    }
  })

  splashWindow.loadFile(path.join(appDir, 'build', 'splash.html'), { query: { v: Date.now() } }).catch(err => {
    console.error('Error loading splash.html:', err)
  })
  splashWindow.on('closed', () => {
    splashWindow = null
  })
}

function createWindow() {
  const appDir = getAppDir()

  mainWindow = new BrowserWindow({
    width: 1280,
    height: 800,
    minWidth: 900,
    minHeight: 600,
    title: "CatChat",
    icon: path.join(appDir, 'build', 'icon.png'),
    autoHideMenuBar: true,
    show: false,
    // The OS title bar is replaced by the in-app one. `hidden` (rather than
    // `frame: false`) keeps the native resize borders, shadow and snap
    // behaviour — only the caption strip goes away.
    titleBarStyle: 'hidden',
    backgroundColor: '#0d0e14',
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      nodeIntegration: false,
      contextIsolation: true,
      sandbox: false,
    }
  })

  // Register command runner IPC handlers
  registerCommandRunnerIPC(mainWindow)
  registerPluginInstallerIPC(mainWindow)

  // Auto-grant the permissions the app itself asks for. `fullscreen` belongs
  // here: Chromium routes `element.requestFullscreen()` through this handler,
  // so leaving it out made every HTML fullscreen request reject and the UI fell
  // back to filling the window instead of the monitor.
  mainWindow.webContents.session.setPermissionRequestHandler(
    (webContents, permission, callback) => {
      const allowedPermissions = ['media', 'mediaKeySystem', 'fullscreen']
      callback(allowedPermissions.includes(permission))
    },
  )

  // Keep the renderer in step with the window when fullscreen is toggled from
  // outside the page (F11, the title bar, the OS).
  mainWindow.on('enter-full-screen', () => {
    mainWindow?.webContents.send('window:fullscreen-changed', true)
  })
  mainWindow.on('leave-full-screen', () => {
    mainWindow?.webContents.send('window:fullscreen-changed', false)
  })

  // Same for maximise: double-clicking the drag region, Win+Up and the OS snap
  // gestures all bypass the in-app button, and its icon has to follow.
  mainWindow.on('maximize', () => {
    mainWindow?.webContents.send('window:maximize-changed', true)
  })
  mainWindow.on('unmaximize', () => {
    mainWindow?.webContents.send('window:maximize-changed', false)
  })

  // Set up display media request handler for screen sharing
  session.defaultSession.setDisplayMediaRequestHandler(
    (request, callback) => {
      desktopCapturer.getSources({ types: ['screen', 'window'] }).then((sources) => {
        pendingScreenSources = sources
        pendingDisplayMediaCallback = callback
        mainWindow.webContents.send('screen-share:sources',
          sources.map(s => ({ id: s.id, name: s.name, thumbnail: s.thumbnail.toDataURL() })))
      }).catch(() => {
        callback(undefined)
      })
    },
    { useSystemPicker: false },
  )

  ipcMain.handle('screen-share:select', (_e, sourceId) => {
    if (pendingDisplayMediaCallback) {
      if (sourceId) {
        const source = pendingScreenSources.find(s => s.id === sourceId)
        pendingDisplayMediaCallback(source ? { video: source } : undefined)
      } else {
        pendingDisplayMediaCallback(undefined)
      }
      pendingDisplayMediaCallback = null
      pendingScreenSources = []
    }
  })

  mainWindow.webContents.on('did-fail-load', (event, errorCode, errorDescription, validatedURL, isMainFrame) => {
    console.error('Electron failed to load URL:', validatedURL, errorCode, errorDescription)
  })

  mainWindow.webContents.on('console-message', (event, level, message, line, sourceId) => {
    console.log('Electron console:', level, message, line, sourceId)
  })

  // Garantizar que la ventana principal se muestre primero antes de cerrar el splash
  let hasShownWindow = false
  const showMainAppWindow = () => {
    if (hasShownWindow) return
    hasShownWindow = true
    if (mainWindow && !mainWindow.isDestroyed()) {
      mainWindow.show()
      mainWindow.focus()
    }
    if (splashWindow && !splashWindow.isDestroyed()) {
      try {
        splashWindow.close()
      } catch {}
    }
  }

  mainWindow.once('ready-to-show', () => {
    setTimeout(() => {
      showMainAppWindow()
    }, 1200)
  })

  // Fallback de seguridad: si ready-to-show tarda más de 3.5s en dispararse, forzar mostrar la ventana principal
  setTimeout(() => {
    showMainAppWindow()
  }, 3500)

  mainWindow.on('closed', function () {
    mainWindow = null
  })

  // Carga la URL del servidor local de desarrollo o la URL de produccion de Vercel
  const startUrl = process.env.ELECTRON_START_URL || 'https://catchat-three.vercel.app'
  mainWindow.loadURL(startUrl)
}

async function startNextServer() {
  if (process.env.ELECTRON_START_URL || !process.env.USE_LOCAL_NEXT_SERVER) {
    return
  }

  const appDir = getAppDir()
  process.env.NODE_ENV = process.env.NODE_ENV || 'production'
  const nextApp = next({ dev: false, dir: appDir })
  const handle = nextApp.getRequestHandler()

  await nextApp.prepare()

  nextServer = http.createServer((req, res) => {
    return handle(req, res)
  })

  return new Promise((resolve, reject) => {
    nextServer.once('error', (err) => {
      reject(err)
    })
    nextServer.listen(3000, '127.0.0.1', () => {
      resolve()
    })
  })
}

app.on('ready', async () => {
  createSplashWindow()
  try {
    setupAutoUpdater()
    registerWindowIPC()
    if (process.env.USE_LOCAL_NEXT_SERVER) {
      await startNextServer()
    }
    createWindow()
    function checkUpdate() {
      try {
        autoUpdater.checkForUpdatesAndNotify().catch((err) => {
          console.log('[AutoUpdater] Check skipped:', err?.message || err)
        })
      } catch (err) {
        console.log('[AutoUpdater] Not configured:', err?.message || err)
      }
    }

    setTimeout(checkUpdate, 8000)
    setInterval(checkUpdate, 2 * 60 * 60 * 1000)
  } catch (error) {
    console.error('Failed to start Next.js server:', error)
    const { dialog } = require('electron')
    if (splashWindow && !splashWindow.isDestroyed()) {
      splashWindow.close()
    }
    dialog.showErrorBox(
      'Error de inicio',
      `No se pudo iniciar el servidor embebido de Next.js.\n\nEsto suele suceder si el puerto 3000 ya está siendo utilizado por otra aplicación (como tu servidor de desarrollo local).\n\nDetalles: ${error.message}`
    )
    app.quit()
  }
})

app.on('window-all-closed', function () {
  // No cerrar el proceso si la ventana principal aún existe o está cargando
  if (mainWindow && !mainWindow.isDestroyed()) {
    return
  }
  if (process.platform !== 'darwin') {
    app.quit()
  }
})

app.on('activate', function () {
  if (mainWindow === null) {
    createWindow()
  }
})

