// hooks/use-command-runner.ts
"use client";
import { useEffect, useRef, useState, useCallback } from "react";

interface CommandRunnerAPI {
  listCommands: () => Promise<string[]>;
  run: (scriptName: string) => Promise<{ runId: string; scriptName: string }>;
  cancel: (runId: string) => Promise<boolean>;
  onOutput: (callback: (payload: OutputPayload) => void) => () => void;
  onStatus: (callback: (payload: StatusPayload) => void) => () => void;
}

interface OutputPayload {
  runId: string;
  stream: "stdout" | "stderr";
  chunk: string;
}

interface StatusPayload {
  runId: string;
  scriptName: string;
  status: "running" | "success" | "error" | "cancelled";
  exitCode?: number;
  error?: string;
}

interface LogLine {
  stream: "stdout" | "stderr";
  text: string;
}

interface RunState {
  scriptName: string;
  status: "running" | "success" | "error" | "cancelled";
  exitCode?: number;
  error?: string;
  lines: LogLine[];
}

declare global {
  interface Window {
    commandRunner?: CommandRunnerAPI;
  }
}

export function useCommandRunner() {
  const [commands, setCommands] = useState<string[]>([]);
  const [runs, setRuns] = useState<Record<string, RunState>>({});

  const runsRef = useRef(runs);
  runsRef.current = runs;

  useEffect(() => {
    if (!window.commandRunner) return; // not running inside Electron (e.g. plain browser)

    window.commandRunner.listCommands().then(setCommands);

    const offOutput = window.commandRunner.onOutput(({ runId, stream, chunk }) => {
      setRuns((prev) => {
        const run = prev[runId];
        if (!run) return prev;
        return {
          ...prev,
          [runId]: {
            ...run,
            lines: [...run.lines, { stream, text: chunk }],
          },
        };
      });
    });

    const offStatus = window.commandRunner.onStatus(({ runId, scriptName, status, exitCode, error }) => {
      setRuns((prev) => ({
        ...prev,
        [runId]: {
          scriptName,
          status,
          exitCode,
          error,
          lines: prev[runId]?.lines ?? [],
        },
      }));
    });

    return () => {
      offOutput();
      offStatus();
    };
  }, []);

  const run = useCallback(async (scriptName: string) => {
    if (!window.commandRunner) {
      throw new Error("Command runner not available outside Electron");
    }
    const { runId } = await window.commandRunner.run(scriptName);
    setRuns((prev) => ({
      ...prev,
      [runId]: { scriptName, status: "running", lines: [] },
    }));
    return runId;
  }, []);

  const cancel = useCallback(async (runId: string) => {
    if (!window.commandRunner) {
      return false;
    }
    return window.commandRunner.cancel(runId);
  }, []);

  return { commands, runs, run, cancel };
}

'use client'

import { useCallback, useEffect, useRef, useState } from 'react'

export type Prefs = {
  desktopNotifications: boolean
  messageSounds: boolean
  enterToSend: boolean
  showOnlineStatus: boolean
  readReceipts: boolean
  muteUntil: string | null
  newContactNotifications: boolean
  whoCanMessage: 'everyone' | 'contacts'
  hideLastSeen: boolean
  fontSize: 'small' | 'medium' | 'large'
  chatDensity: 'compact' | 'normal' | 'spacious'
  timeFormat: '12h' | '24h'
  showTimestamps: boolean
  language: string
  timezone: string
}

function getDefaultTimezone(): string {
  if (typeof window === 'undefined') return 'UTC'
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone
  } catch {
    return 'UTC'
  }
}

export const DEFAULT_PREFS: Prefs = {
  desktopNotifications: true,
  messageSounds: true,
  enterToSend: true,
  showOnlineStatus: true,
  readReceipts: true,
  muteUntil: null,
  newContactNotifications: true,
  whoCanMessage: 'everyone',
  hideLastSeen: false,
  fontSize: 'medium',
  chatDensity: 'normal',
  timeFormat: '24h',
  showTimestamps: true,
  language: 'en',
  timezone: 'UTC',
}

export const PREFS_KEY = 'cz-prefs'

function readPrefs(): Prefs {
  if (typeof window === 'undefined') return DEFAULT_PREFS
  try {
    const raw = localStorage.getItem(PREFS_KEY)
    if (raw) return { ...DEFAULT_PREFS, ...JSON.parse(raw) }
  } catch {
    /* ignore */
  }
  return DEFAULT_PREFS
}

export function usePrefs() {
  const [prefs, setPrefs] = useState<Prefs>(DEFAULT_PREFS)
  const prefsRef = useRef(prefs)
  prefsRef.current = prefs

  useEffect(() => {
    setPrefs(readPrefs())
    const handler = () => setPrefs(readPrefs())
    window.addEventListener('cz-prefs-changed', handler)
    return () => window.removeEventListener('cz-prefs-changed', handler)
  }, [])

  const update = useCallback((patch: Partial<Prefs>) => {
    const next = { ...prefsRef.current, ...patch }
    localStorage.setItem(PREFS_KEY, JSON.stringify(next))
    setPrefs(next)
    window.dispatchEvent(new Event('cz-prefs-changed'))
  }, [])

  return [prefs, update] as const
}

/**
 * Server-only YouTube InnerTube client + resilient response parser.
 *
 * Why this exists: YouTube migrated most surfaces from the classic
 * `*Renderer` objects to the newer `lockupViewModel` shape. Playlist
 * browse responses in particular now contain ZERO `playlistVideoRenderer`
 * entries, which is why fixed-path scraping returned empty lists.
 *
 * Everything here is defensive: we recursively collect known node types
 * anywhere in the payload instead of walking brittle fixed paths, so a
 * layout change on YouTube's side degrades instead of breaking.
 */

import type { Track } from './types'

const INNERTUBE_KEY = process.env.YOUTUBE_INNERTUBE_KEY || 'AIzaSyAO_FJ2SlqU8Q4STEHLGCilw_Y9_11qcW8'
const CLIENT_VERSION = process.env.YOUTUBE_CLIENT_VERSION || '2.20250801.00.00'
const UA =
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36'

/** How long a successful InnerTube payload stays reusable. */
const CACHE_TTL_MS = 5 * 60 * 1000
/** Hard ceiling on cached payloads, so a search-spamming client can't grow the heap. */
const CACHE_MAX_ENTRIES = 200
/** Network attempts per call: one try plus two retries with backoff. */
const MAX_ATTEMPTS = 3

export type YtPlaylist = {
  id: string
  playlistId: string
  title: string
  artist: string
  videoCount: string
  coverUrl: string
  tracks: Track[]
}

export type YtChannel = {
  id: string
  name: string
  avatarUrl: string
  subtitle: string
  bannerUrl?: string
}

/**
 * Every high-level helper reports whether YouTube actually answered.
 * Without this an upstream outage is indistinguishable from "no results",
 * and the UI ends up lying to the user with an empty state.
 */
export type Upstream<T> = T & { ok: boolean }

/** Search filter params (protobuf, url-encoded) */
export const SEARCH_FILTER = {
  video: 'EgIQAQ%3D%3D',
  channel: 'EgIQAg%3D%3D',
  playlist: 'EgIQAw%3D%3D',
} as const

export type SearchFilter = keyof typeof SEARCH_FILTER

type InnertubeResult = { ok: boolean; json: any | null }

const cache = new Map<string, { json: any; expiresAt: number }>()

function cacheGet(key: string): any | null {
  const hit = cache.get(key)
  if (!hit) return null
  if (Date.now() >= hit.expiresAt) {
    cache.delete(key)
    return null
  }
  // Refresh insertion order so the LRU eviction below drops cold entries first.
  cache.delete(key)
  cache.set(key, hit)
  return hit.json
}

function cacheSet(key: string, json: any) {
  cache.set(key, { json, expiresAt: Date.now() + CACHE_TTL_MS })
  while (cache.size > CACHE_MAX_ENTRIES) {
    const oldest = cache.keys().next().value
    if (oldest === undefined) break
    cache.delete(oldest)
  }
}

/** Exposed for tests and for an eventual admin "flush caches" action. */
export function clearInnertubeCache() {
  cache.clear()
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

/**
 * Low-level InnerTube POST: timeout, retry with backoff, and a TTL cache.
 *
 * Retries only on network errors and 5xx/429 — a 4xx means the request itself
 * is wrong, so hammering it again just wastes the budget.
 */
async function innertube(
  endpoint: string,
  body: Record<string, unknown>,
  timeoutMs = 8000,
): Promise<InnertubeResult> {
  const cacheKey = `${endpoint}:${JSON.stringify(body)}`
  const cached = cacheGet(cacheKey)
  if (cached) return { ok: true, json: cached }

  let retryable = true

  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    const controller = new AbortController()
    const timer = setTimeout(() => controller.abort(), timeoutMs)

    try {
      const res = await fetch(
        `https://www.youtube.com/youtubei/v1/${endpoint}?key=${INNERTUBE_KEY}&prettyPrint=false`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'User-Agent': UA,
            'Accept-Language': 'es-ES,es;q=0.9,en;q=0.8',
            Origin: 'https://www.youtube.com',
          },
          body: JSON.stringify({
            context: {
              client: {
                clientName: 'WEB',
                clientVersion: CLIENT_VERSION,
                hl: 'es',
                gl: 'ES',
              },
            },
            ...body,
          }),
          signal: controller.signal,
          cache: 'no-store',
        },
      )

      if (!res.ok) {
        // 429 and 5xx are worth another attempt; the rest are not.
        retryable = res.status === 429 || res.status >= 500
        if (!retryable) return { ok: false, json: null }
      } else {
        const json = (await res.json()) as any
        cacheSet(cacheKey, json)
        return { ok: true, json }
      }
    } catch {
      // Network failure or timeout — retryable.
      retryable = true
    } finally {
      clearTimeout(timer)
    }

    if (attempt < MAX_ATTEMPTS && retryable) {
      await sleep(250 * 2 ** (attempt - 1))
    }
  }

  return { ok: false, json: null }
}

/**
 * Single-pass recursive collector.
 *
 * The previous implementation walked the whole payload once per key, so
 * `extractVideos` traversed a multi-megabyte tree eight times. This walks it
 * once and buckets every interesting node by key.
 */
function deepCollect(node: any, keys: readonly string[]): Map<string, any[]> {
  const out = new Map<string, any[]>()
  for (const key of keys) out.set(key, [])
  const wanted = out

  const walk = (current: any) => {
    if (!current || typeof current !== 'object') return

    if (Array.isArray(current)) {
      for (const item of current) walk(item)
      return
    }

    for (const k of Object.keys(current)) {
      const bucket = wanted.get(k)
      if (bucket) bucket.push(current[k])
      // Descend even into matched nodes: renderers can nest, and the
      // per-key dedupe downstream makes an extra hit harmless.
      walk(current[k])
    }
  }

  walk(node)
  return out
}

/** Recursively collect every value stored under `key`. */
function deepFind(node: any, key: string, out: any[] = []): any[] {
  if (!node || typeof node !== 'object') return out

  if (Array.isArray(node)) {
    for (const item of node) deepFind(item, key, out)
    return out
  }

  for (const k of Object.keys(node)) {
    if (k === key) out.push(node[k])
    else deepFind(node[k], key, out)
  }
  return out
}

/** "3:34" | "1:02:11" -> seconds. Returns 0 when unparseable. */
export function parseDurationText(text: unknown): number {
  if (typeof text !== 'string') return 0
  const m = text.trim().match(/^(?:(\d+):)?(\d{1,2}):(\d{2})$/)
  if (!m) return 0
  const h = m[1] ? parseInt(m[1], 10) : 0
  const min = parseInt(m[2], 10)
  const s = parseInt(m[3], 10)
  return h * 3600 + min * 60 + s
}

/** Stable, param-free thumbnail that never 404s. */
function thumb(videoId: string): string {
  return videoId ? `https://i.ytimg.com/vi/${videoId}/mqdefault.jpg` : '/placeholder.svg'
}

/** Pull a video id out of any i.ytimg.com thumbnail URL. */
function videoIdFromThumbUrl(url: unknown): string {
  if (typeof url !== 'string') return ''
  return url.match(/\/vi\/([A-Za-z0-9_-]{11})\//)?.[1] || ''
}

const isVideoId = (v: unknown): v is string =>
  typeof v === 'string' && /^[A-Za-z0-9_-]{11}$/.test(v)

/** First duration-looking badge text inside a lockup thumbnail. */
function durationFromLockup(lockup: any): number {
  const badges = deepFind(lockup?.contentImage, 'thumbnailBadgeViewModel')
  for (const b of badges) {
    const secs = parseDurationText(b?.text)
    if (secs > 0) return secs
  }
  return 0
}

/**
 * Title + subtitle out of lockupMetadataViewModel.
 *
 * `subtitle` skips rows that start with a digit, because in video lockups the
 * first row is the view count and the channel name comes after it. `rows` keeps
 * every row verbatim for callers where a leading digit is the point (a channel
 * lockup's subtitle *is* its subscriber count).
 */
function metaFromLockup(lockup: any): { title: string; subtitle: string; rows: string[] } {
  const meta = lockup?.metadata?.lockupMetadataViewModel
  const title = typeof meta?.title?.content === 'string' ? meta.title.content : ''

  const metadataRows = meta?.metadata?.contentMetadataViewModel?.metadataRows
  const rows: string[] = []
  if (Array.isArray(metadataRows)) {
    for (const row of metadataRows) {
      const part = row?.metadataParts?.[0]?.text?.content
      if (typeof part === 'string' && part.trim()) rows.push(part)
    }
  }

  const subtitle = rows.find((r) => !/^\d/.test(r)) ?? ''
  return { title, subtitle, rows }
}

/** Classic renderer keys that all expose the same `videoId`/`title`/`lengthText` shape. */
const CLASSIC_VIDEO_KEYS = [
  'videoRenderer',
  'playlistVideoRenderer',
  'compactVideoRenderer',
  'gridVideoRenderer',
  'playlistPanelVideoRenderer',
] as const

const VIDEO_KEYS = [
  'musicResponsiveListItemRenderer',
  'musicTwoRowItemRenderer',
  ...CLASSIC_VIDEO_KEYS,
  'lockupViewModel',
] as const

/**
 * Extract playable tracks from ANY InnerTube payload.
 * Handles videoRenderer, playlistVideoRenderer, compactVideoRenderer,
 * gridVideoRenderer and the modern lockupViewModel.
 */
export function extractVideos(json: any, opts: { requireDuration?: boolean } = {}): Track[] {
  const { requireDuration = false } = opts
  const tracks: Track[] = []
  const seen = new Set<string>()
  const nodes = deepCollect(json, VIDEO_KEYS)

  const push = (
    id: string,
    title: string,
    artist: string,
    seconds: number,
    album: string,
  ) => {
    if (!isVideoId(id) || seen.has(id)) return
    if (!title) return
    if (requireDuration && seconds <= 0) return // drops live streams / shorts shells
    seen.add(id)
    tracks.push({
      id,
      title: title.trim(),
      artist: (artist || 'YouTube Music').trim(),
      album,
      durationSeconds: seconds > 0 ? seconds : 0,
      artworkUrl: thumb(id),
      source: 'youtube',
    })
  }

  // --- YouTube Music renderers (different structure) ---
  for (const mr of nodes.get('musicResponsiveListItemRenderer') ?? []) {
    const flex0 = mr?.flexColumns?.[0]?.musicResponsiveListItemFlexColumnRenderer?.text?.runs
    const flex1 = mr?.flexColumns?.[1]?.musicResponsiveListItemFlexColumnRenderer?.text?.runs
    const titleRun = flex0?.[0]
    const id =
      titleRun?.navigationEndpoint?.watchEndpoint?.videoId ||
      mr?.overlay?.musicItemThumbnailOverlayRenderer?.content?.musicPlayButtonRenderer?.playNavigationEndpoint?.watchEndpoint?.videoId ||
      mr?.playlistItemData?.videoId
    const title = titleRun?.text || ''
    const artist = flex1 ? flex1.filter((r: any) => !/^\d/.test(r.text) && !/^\d+:\d+/.test(r.text)).map((r: any) => r.text).join('') : ''
    const durationText = flex1 ? flex1[flex1.length - 1]?.text : ''
    const seconds = parseDurationText(durationText)
    push(id, title, artist, seconds, 'YouTube')
  }

  for (const mr of nodes.get('musicTwoRowItemRenderer') ?? []) {
    const nav = mr?.navigationEndpoint?.watchEndpoint
    const id = nav?.videoId || mr?.title?.runs?.[0]?.navigationEndpoint?.watchEndpoint?.videoId
    const title = mr?.title?.runs?.[0]?.text || ''
    const subtitles = mr?.subtitle?.runs
    const artist = subtitles ? subtitles.filter((r: any) => !/^\d/.test(r.text) && !/^\d+:\d+/.test(r.text)).map((r: any) => r.text).join('') : ''
    const durationText = subtitles ? subtitles[subtitles.length - 1]?.text : ''
    const seconds = parseDurationText(durationText)
    push(id, title, artist, seconds, 'YouTube')
  }

  // --- classic renderers ---
  for (const key of CLASSIC_VIDEO_KEYS) {
    for (const v of nodes.get(key) ?? []) {
      const id = v?.videoId
      const title = v?.title?.simpleText || v?.title?.runs?.[0]?.text || ''
      const artist =
        v?.ownerText?.runs?.[0]?.text ||
        v?.shortBylineText?.runs?.[0]?.text ||
        v?.longBylineText?.runs?.[0]?.text ||
        v?.shortBylineText?.simpleText ||
        v?.longBylineText?.simpleText ||
        v?.channelTitle?.simpleText ||
        v?.channelTitle?.runs?.[0]?.text ||
        ''
      const seconds =
        parseDurationText(v?.lengthText?.simpleText) ||
        parseDurationText(v?.lengthText?.runs?.[0]?.text) ||
        (v?.lengthSeconds ? parseInt(v.lengthSeconds, 10) : 0)

      push(id, title, artist, seconds, 'YouTube')
    }
  }

  // --- modern lockups ---
  for (const lockup of nodes.get('lockupViewModel') ?? []) {
    if (lockup?.contentType && lockup.contentType !== 'LOCKUP_CONTENT_TYPE_VIDEO') continue

    const id = isVideoId(lockup?.contentId)
      ? lockup.contentId
      : videoIdFromThumbUrl(
          deepFind(lockup?.contentImage, 'sources')?.[0]?.[0]?.url,
        )

    const { title, subtitle } = metaFromLockup(lockup)
    push(id, title, subtitle, durationFromLockup(lockup), 'YouTube')
  }

  return tracks
}

/** Extract playlists/albums from ANY InnerTube payload. */
export function extractPlaylists(json: any): YtPlaylist[] {
  const results: YtPlaylist[] = []
  const seen = new Set<string>()
  const nodes = deepCollect(json, ['playlistRenderer', 'gridPlaylistRenderer', 'lockupViewModel'])

  const push = (
    playlistId: string,
    title: string,
    artist: string,
    videoCount: string,
    coverUrl: string,
  ) => {
    if (!playlistId || seen.has(playlistId) || !title) return
    // Radio/mix ids aren't browsable as playlists
    if (playlistId.startsWith('RD')) return
    seen.add(playlistId)
    results.push({
      id: playlistId,
      playlistId,
      title: title.trim(),
      artist: (artist || '').trim(),
      videoCount: videoCount || '',
      coverUrl: coverUrl || '/placeholder.svg',
      tracks: [],
    })
  }

  // --- classic renderers ---
  for (const key of ['playlistRenderer', 'gridPlaylistRenderer'] as const) {
    for (const p of nodes.get(key) ?? []) {
      const firstVideo = p?.navigationEndpoint?.watchEndpoint?.videoId
      const rawThumb =
        p?.thumbnails?.[0]?.thumbnails?.slice(-1)?.[0]?.url ||
        p?.thumbnail?.thumbnails?.slice(-1)?.[0]?.url
      const coverId = isVideoId(firstVideo) ? firstVideo : videoIdFromThumbUrl(rawThumb)

      push(
        p?.playlistId,
        p?.title?.simpleText || p?.title?.runs?.[0]?.text || '',
        p?.shortBylineText?.runs?.[0]?.text || p?.longBylineText?.runs?.[0]?.text || '',
        p?.videoCountText?.runs?.[0]?.text || p?.videoCountShortText?.simpleText || '',
        coverId ? thumb(coverId) : rawThumb || '/placeholder.svg',
      )
    }
  }

  // --- modern lockups ---
  for (const lockup of nodes.get('lockupViewModel') ?? []) {
    if (lockup?.contentType !== 'LOCKUP_CONTENT_TYPE_PLAYLIST') continue

    const { title, subtitle } = metaFromLockup(lockup)

    // count badge, e.g. "37 vídeos"
    let count = ''
    for (const b of deepFind(lockup?.contentImage, 'thumbnailBadgeViewModel')) {
      if (typeof b?.text === 'string' && /\d/.test(b.text) && !parseDurationText(b.text)) {
        count = b.text
        break
      }
    }

    const coverId = videoIdFromThumbUrl(
      deepFind(lockup?.contentImage, 'sources')?.[0]?.[0]?.url,
    )

    push(lockup?.contentId, title, subtitle, count, coverId ? thumb(coverId) : '/placeholder.svg')
  }

  return results
}

/** Normalize a YouTube avatar/snippet URL to always use https: and be displayable. */
function normalizeAvatarUrl(url: string): string {
  if (!url) return ''
  // YouTube often serves protocol-relative URLs: "//yt3.ggpht.com/..."
  if (url.startsWith('//')) return `https:${url}`
  if (url.startsWith('/')) return `https:${url}`
  return url
}

/** Extract channels from a channel-filtered search payload. */
export function extractChannels(json: any): YtChannel[] {
  const out: YtChannel[] = []
  const seen = new Set<string>()
  const nodes = deepCollect(json, ['channelRenderer', 'lockupViewModel'])

  // --- classic channelRenderer ---
  for (const c of nodes.get('channelRenderer') ?? []) {
    const id = c?.channelId
    const name = c?.title?.simpleText || c?.title?.runs?.[0]?.text || ''
    if (!id || !name || seen.has(id)) continue
    seen.add(id)

    const avatar =
      c?.thumbnail?.thumbnails?.slice(-1)?.[0]?.url ||
      c?.avatar?.thumbnails?.slice(-1)?.[0]?.url ||
      ''

    out.push({
      id,
      name: name.trim(),
      avatarUrl: normalizeAvatarUrl(avatar) || '/placeholder.svg',
      subtitle: c?.videoCountText?.simpleText || c?.subscriberCountText?.simpleText || '',
      bannerUrl: c?.banner?.thumbnails?.slice(-1)?.[0]?.url || c?.mobileBanner?.thumbnails?.slice(-1)?.[0]?.url || undefined,
    })
  }

  // --- modern lockupViewModel shape (e.g. channel search results) ---
  for (const lockup of nodes.get('lockupViewModel') ?? []) {
    if (lockup?.contentType !== 'LOCKUP_CONTENT_TYPE_CHANNEL') continue

    const id = lockup?.contentId
    const { title, subtitle, rows } = metaFromLockup(lockup)
    if (!id || !title || seen.has(id)) continue
    seen.add(id)

    // Avatar from lockup contentImage
    let avatar = ''
    const srcs = deepFind(lockup?.contentImage, 'sources')
    if (srcs?.[0]?.[0]?.url) avatar = srcs[0][0].url
    else if (srcs?.[0]?.url) avatar = srcs[0].url

    // Also try thumbnail
    if (!avatar) {
      for (const t of deepFind(lockup, 'thumbnail')) {
        if (typeof t?.url === 'string') { avatar = t.url; break }
      }
    }

    // Try to extract banner from lockup metadata
    let banner: string | undefined
    const bannerSrcs = deepFind(lockup, 'banner')
    for (const b of bannerSrcs) {
      const t = b?.thumbnails?.slice(-1)?.[0]?.url
      if (t) { banner = t; break }
    }

    out.push({
      id,
      name: (title || '').trim(),
      avatarUrl: normalizeAvatarUrl(avatar) || '/placeholder.svg',
      // A channel's subtitle is usually "120K subscribers", which the
      // digit-skipping subtitle heuristic throws away — fall back to row 0.
      subtitle: (subtitle || rows[0] || '').trim(),
      bannerUrl: banner,
    })
  }

  return out
}

/* ------------------------------------------------------------------ */
/* High-level helpers                                                  */
/* ------------------------------------------------------------------ */

/**
 * Pull a banner URL out of a payload we already have, instead of spending an
 * extra browse request on it.
 */
export function extractBanner(json: any): string | undefined {
  if (!json) return undefined

  for (const key of ['banner', 'mobileBanner', 'tvBanner']) {
    for (const item of deepFind(json, key)) {
      const url =
        item?.thumbnails?.slice(-1)?.[0]?.url ||
        item?.thumbnails?.[0]?.url ||
        (typeof item?.url === 'string' ? item.url : undefined)
      if (typeof url === 'string' && url) return normalizeAvatarUrl(url)
    }
  }

  return undefined
}

export async function searchVideos(query: string): Promise<Upstream<{ tracks: Track[] }>> {
  const { ok, json } = await innertube('search', { query, params: SEARCH_FILTER.video })
  if (!ok || !json) return { ok, tracks: [] }
  return { ok: true, tracks: extractVideos(json, { requireDuration: true }) }
}

export async function searchPlaylists(query: string): Promise<Upstream<{ playlists: YtPlaylist[] }>> {
  const { ok, json } = await innertube('search', { query, params: SEARCH_FILTER.playlist })
  if (!ok || !json) return { ok, playlists: [] }
  return { ok: true, playlists: extractPlaylists(json) }
}

export async function searchChannels(query: string): Promise<Upstream<{ channels: YtChannel[] }>> {
  const { ok, json } = await innertube('search', { query, params: SEARCH_FILTER.channel })
  if (!ok || !json) return { ok, channels: [] }
  return { ok: true, channels: extractChannels(json) }
}

/** Tracks inside a playlist. `VL` prefix = "view list". */
export async function getPlaylistTracks(
  playlistId: string,
): Promise<Upstream<{ title: string; tracks: Track[] }>> {
  const clean = playlistId.replace(/^VL/, '')
  const { ok, json } = await innertube('browse', { browseId: `VL${clean}` })
  if (!ok || !json) return { ok, title: '', tracks: [] }

  const title =
    deepFind(json, 'playlistHeaderRenderer')?.[0]?.title?.simpleText ||
    deepFind(json, 'pageHeaderRenderer')?.[0]?.pageTitle ||
    ''

  return { ok: true, title, tracks: extractVideos(json) }
}

/**
 * A channel's uploads + its official playlists + banner.
 *
 * The banner is read from the two payloads we already fetch, so an artist page
 * costs two upstream requests instead of the three it used to.
 */
export async function getChannel(
  channelId: string,
): Promise<Upstream<{ tracks: Track[]; playlists: YtPlaylist[]; bannerUrl?: string }>> {
  const [videosTab, playlistsTab] = await Promise.all([
    // EgZ2aWRlb3M% = "videos" tab
    innertube('browse', { browseId: channelId, params: 'EgZ2aWRlb3PyBgQKAjoA' }),
    // EglwbGF5bGlzdHM% = "playlists" tab
    innertube('browse', { browseId: channelId, params: 'EglwbGF5bGlzdHPyBgQKAkIA' }),
  ])

  return {
    // A channel is only a hard failure when neither tab came back.
    ok: videosTab.ok || playlistsTab.ok,
    tracks: videosTab.json ? extractVideos(videosTab.json) : [],
    playlists: playlistsTab.json ? extractPlaylists(playlistsTab.json) : [],
    bannerUrl: extractBanner(videosTab.json) ?? extractBanner(playlistsTab.json),
  }
}

'use client'

import React, { createContext, useContext, useCallback, useEffect, useRef, useState } from 'react'
import type { Playlist, PlayHistoryEntry, CatMusicSettings, Track } from './types'
import { loadCatMusicLibrary, saveCatMusicLibrary } from '@/app/actions/catmusic-favorites'

type LibraryContextType = {
  favorites: Track[]
  playlists: Playlist[]
  history: PlayHistoryEntry[]
  settings: CatMusicSettings
  toggleFavorite: (track: Track) => void
  isFavorite: (trackId: string) => boolean
  createPlaylist: (name: string, description?: string) => Playlist
  deletePlaylist: (playlistId: string) => void
  addTrackToPlaylist: (playlistId: string, track: Track) => void
  removeTrackFromPlaylist: (playlistId: string, trackId: string) => void
  recordPlay: (track: Track, msPlayed: number, completed: boolean) => void
  clearHistory: () => void
  saveSettings: (patch: Partial<CatMusicSettings>) => void
}

const LibraryContext = createContext<LibraryContextType | null>(null)

const STORAGE_KEY = 'catmusic-library-v1'

const DEFAULT_SETTINGS: CatMusicSettings = {
  autoplay: true,
  defaultVolume: 80,
}

const DEFAULT_PLAYLISTS: Playlist[] = []

/** The history is capped so the persisted blob can't grow without bound. */
const HISTORY_LIMIT = 100

function newerIso(a?: string, b?: string): boolean {
  const ta = a ? Date.parse(a) : NaN
  const tb = b ? Date.parse(b) : NaN
  if (Number.isNaN(ta)) return false
  if (Number.isNaN(tb)) return true
  return ta > tb
}

/**
 * Union by id, local order first.
 *
 * Length was the old tie-breaker ("prefer whichever side has more"), which
 * dropped items added on this device whenever the server copy happened to be
 * longer. Without delete tombstones a union is the only merge that can't lose
 * data; the cost is that a removal on another device can come back.
 */
function mergeById<T extends { id?: string }>(local: T[], remote: T[]): T[] {
  const out: T[] = []
  const seen = new Set<string>()
  for (const item of [...local, ...remote]) {
    const id = item?.id
    if (!id || seen.has(id)) continue
    seen.add(id)
    out.push(item)
  }
  return out
}

/** Same union, but a playlist present on both sides resolves by `updatedAt`. */
function mergePlaylists(local: Playlist[], remote: Playlist[]): Playlist[] {
  const byId = new Map<string, Playlist>()
  for (const pl of local) {
    if (pl?.id) byId.set(pl.id, pl)
  }
  for (const pl of remote) {
    if (!pl?.id) continue
    const mine = byId.get(pl.id)
    if (!mine) {
      byId.set(pl.id, pl)
      continue
    }
    const winner = newerIso(pl.updatedAt, mine.updatedAt) ? pl : mine
    byId.set(pl.id, {
      ...winner,
      // Tracks union either way: a song added on one device shouldn't vanish
      // just because the other device touched the playlist later.
      tracks: mergeById(mine.tracks || [], pl.tracks || []),
    })
  }
  // Keep local ordering, then anything only the server knew about.
  const ordered: Playlist[] = []
  const emitted = new Set<string>()
  for (const pl of [...local, ...remote]) {
    if (!pl?.id || emitted.has(pl.id)) continue
    emitted.add(pl.id)
    const merged = byId.get(pl.id)
    if (merged) ordered.push(merged)
  }
  return ordered
}

function mergeHistory(local: PlayHistoryEntry[], remote: PlayHistoryEntry[]): PlayHistoryEntry[] {
  return mergeById(local, remote)
    .sort((a, b) => Date.parse(b.playedAt || '') - Date.parse(a.playedAt || ''))
    .slice(0, HISTORY_LIMIT)
}

/**
 * Keeps only settings the player honors, so keys from a removed feature don't
 * ride along in storage forever.
 */
function sanitizeSettings(raw: unknown): CatMusicSettings {
  const patch = (raw || {}) as Partial<CatMusicSettings>
  const volume = Number(patch.defaultVolume)
  return {
    autoplay: typeof patch.autoplay === 'boolean' ? patch.autoplay : DEFAULT_SETTINGS.autoplay,
    defaultVolume: Number.isFinite(volume)
      ? Math.max(0, Math.min(100, Math.round(volume)))
      : DEFAULT_SETTINGS.defaultVolume,
  }
}

export function LibraryProvider({
  children,
  active = true,
}: {
  children: React.ReactNode
  active?: boolean
}) {
  const [favorites, setFavorites] = useState<Track[]>(() => [])
  const [playlists, setPlaylists] = useState<Playlist[]>(DEFAULT_PLAYLISTS)
  const [history, setHistory] = useState<PlayHistoryEntry[]>([])
  const [settings, setSettings] = useState<CatMusicSettings>(DEFAULT_SETTINGS)
  const loadedRef = useRef(false)

  useEffect(() => {
    if (!active || typeof window === 'undefined') return
    try {
      const saved = localStorage.getItem(STORAGE_KEY)
      if (saved) {
        const parsed = JSON.parse(saved)
        if (Array.isArray(parsed.favorites)) {
          // Early versions stored bare video ids.
          const migrated = parsed.favorites
            .map((f: unknown) =>
              typeof f === 'string'
                ? {
                    id: f,
                    title: f,
                    artist: '',
                    durationSeconds: 0,
                    artworkUrl: '',
                    source: 'youtube' as const,
                  }
                : f,
            )
            .filter((f: Track | null) => f && f.id)
          setFavorites(migrated)
        }
        if (Array.isArray(parsed.playlists)) setPlaylists(parsed.playlists)
        if (Array.isArray(parsed.history)) setHistory(parsed.history)
        if (parsed.settings) setSettings(sanitizeSettings(parsed.settings))
      }
    } catch {
      // Corrupt or unreadable storage: start from the defaults.
    }
    loadedRef.current = true
  }, [active])

  // Sync from Supabase on mount (after local load)
  useEffect(() => {
    if (!active || typeof window === 'undefined' || !loadedRef.current) return
    loadCatMusicLibrary()
      .then((remote) => {
        if (Array.isArray(remote.favorites) && remote.favorites.length > 0) {
          const incoming = (remote.favorites as Track[]).filter((t) => t && t.id)
          setFavorites((prev) => mergeById(prev, incoming))
        }
        if (Array.isArray(remote.playlists) && remote.playlists.length > 0) {
          const incoming = (remote.playlists as Playlist[]).filter((p) => p && p.id)
          setPlaylists((prev) => mergePlaylists(prev, incoming))
        }
        if (Array.isArray(remote.history) && remote.history.length > 0) {
          const incoming = (remote.history as PlayHistoryEntry[]).filter((h) => h && h.id)
          setHistory((prev) => mergeHistory(prev, incoming))
        }
        if (remote.settings && Object.keys(remote.settings).length > 0) {
          setSettings((prev) => sanitizeSettings({ ...prev, ...(remote.settings as object) }))
        }
      })
      .catch(() => {})
  }, [active])

  // Save to Supabase (debounced)
  const supabaseSaveRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const saveToSupabase = useCallback(() => {
    if (typeof window === 'undefined') return
    if (supabaseSaveRef.current) clearTimeout(supabaseSaveRef.current)
    supabaseSaveRef.current = setTimeout(() => {
      saveCatMusicLibrary({
        favorites: favoritesRef.current,
        playlists: playlistsRef.current,
        history: historyRef.current,
        settings: settingsRef.current,
      }).catch(() => {})
    }, 2000)
  }, [])

  const favoritesRef = useRef(favorites)
  const playlistsRef = useRef(playlists)
  const historyRef = useRef(history)
  const settingsRef = useRef(settings)
  favoritesRef.current = favorites
  playlistsRef.current = playlists
  historyRef.current = history
  settingsRef.current = settings

  useEffect(() => {
    if (!active || typeof window === 'undefined' || !loadedRef.current) return
    const snapshot = { favorites, playlists, history, settings }
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(snapshot))
    } catch {
      // Quota exceeded or private mode: the Supabase copy below is still the
      // durable one, so losing the local cache must not break the UI.
    }
    saveToSupabase()
  }, [active, favorites, playlists, history, settings, saveToSupabase])

  const isFavorite = (trackId: string) => favorites.some((t) => t.id === trackId)

  const toggleFavorite = (track: Track) => {
    setFavorites((prev) => {
      if (prev.some((t) => t.id === track.id)) {
        return prev.filter((t) => t.id !== track.id)
      } else {
        return [track, ...prev]
      }
    })
  }

  const createPlaylist = (name: string, description?: string): Playlist => {
    const newPl: Playlist = {
      id: `pl-${Date.now()}`,
      name: name.trim() || 'Playlist',
      description,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      tracks: [],
    }
    setPlaylists((prev) => [newPl, ...prev])
    return newPl
  }

  const deletePlaylist = (playlistId: string) => {
    setPlaylists((prev) => prev.filter((p) => p.id !== playlistId))
  }

  const addTrackToPlaylist = (playlistId: string, track: Track) => {
    setPlaylists((prev) =>
      prev.map((p) => {
        if (p.id === playlistId) {
          if (p.tracks.some((t) => t.id === track.id)) return p
          return {
            ...p,
            tracks: [...p.tracks, track],
            updatedAt: new Date().toISOString(),
          }
        }
        return p
      }),
    )
  }

  const removeTrackFromPlaylist = (playlistId: string, trackId: string) => {
    setPlaylists((prev) =>
      prev.map((p) => {
        if (p.id === playlistId) {
          return {
            ...p,
            tracks: p.tracks.filter((t) => t.id !== trackId),
            updatedAt: new Date().toISOString(),
          }
        }
        return p
      }),
    )
  }

  const recordPlay = useCallback((track: Track, msPlayed: number, completed: boolean) => {
    if (!track?.id) return
    const entry: PlayHistoryEntry = {
      id: `hist-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
      trackId: track.id,
      track,
      playedAt: new Date().toISOString(),
      msPlayed,
      completed,
    }
    setHistory((prev) => [entry, ...prev].slice(0, HISTORY_LIMIT))
  }, [])

  const clearHistory = () => {
    setHistory([])
  }

  const saveSettings = (patch: Partial<CatMusicSettings>) => {
    setSettings((prev) => ({ ...prev, ...patch }))
  }

  return (
    <LibraryContext.Provider
      value={{
        favorites,
        playlists,
        history,
        settings,
        toggleFavorite,
        isFavorite,
        createPlaylist,
        deletePlaylist,
        addTrackToPlaylist,
        removeTrackFromPlaylist,
        recordPlay,
        clearHistory,
        saveSettings,
      }}
    >
      {children}
    </LibraryContext.Provider>
  )
}

const defaultLibraryContext: LibraryContextType = {
  favorites: [],
  playlists: [],
  history: [],
  settings: {
    autoplay: false,
    defaultVolume: 80,
  },
  isFavorite: () => false,
  toggleFavorite: () => {},
  createPlaylist: () => ({ id: '', name: '', tracks: [], createdAt: '', updatedAt: '' }),
  deletePlaylist: () => {},
  addTrackToPlaylist: () => {},
  removeTrackFromPlaylist: () => {},
  recordPlay: () => {},
  clearHistory: () => {},
  saveSettings: () => {},
}

export function useLibrary() {
  const ctx = useContext(LibraryContext)
  return ctx || defaultLibraryContext
}

'use client'

import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useRef,
  useSyncExternalStore,
} from 'react'
import type { PlayerState, RepeatMode, Track } from './types'
import { SEED_TRACKS } from './catalog'
import { ARTWORK_DIMENSIONS, getArtworkUrl, loadYouTubeIframeApi } from './youtube'
import { catMusicStore } from './cat-music-store'
import { useLibrary } from './library-context'

type PlayerContextType = {
  playerState: PlayerState
  currentTrack: Track | null
  playTrack: (track: Track, newQueue?: Track[], context?: { type: string; id?: string }) => void
  togglePlayPause: () => void
  nextTrack: () => void
  previousTrack: () => void
  seekTo: (seconds: number) => void
  setVolume: (volume: number) => void
  toggleMute: () => void
  toggleShuffle: () => void
  cycleRepeat: () => void
  addToQueue: (track: Track) => void
  removeFromQueue: (index: number) => void
  clearQueue: () => void
  stopPlayback: () => void
}

const PlayerContext = createContext<PlayerContextType | null>(null)

/** Twice a second is enough for a progress bar and cheap enough in a timer. */
const TICK_MS = 500

/** Grace period before skipping an unplayable video, so the error is readable. */
const ERROR_SKIP_DELAY_MS = 1500

/** Under this, a play was a skip-through and doesn't belong in the history. */
const MIN_HISTORY_MS = 5000

/** Restored when unmuting from a muted-at-zero state. */
const FALLBACK_UNMUTE_VOLUME = 50

const REPEAT_MODES: RepeatMode[] = ['off', 'all', 'one']

export function CatMusicPlayerProvider({
  children,
  active = true,
}: {
  children: React.ReactNode
  active?: boolean
}) {
  const playerState = useSyncExternalStore(
    catMusicStore.subscribe,
    catMusicStore.getSnapshot,
    catMusicStore.getServerSnapshot,
  )

  const { recordPlay, settings } = useLibrary()

  const ytPlayerRef = useRef<any>(null)
  const isSeekingRef = useRef(false)
  const seekResetRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const errorSkipRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const preMuteVolumeRef = useRef<number>(playerState.volume)

  // Latest-value refs: the YouTube event handlers are registered once, so they
  // must not close over a specific render's props.
  const recordPlayRef = useRef(recordPlay)
  recordPlayRef.current = recordPlay
  const autoplayRef = useRef(settings.autoplay)
  autoplayRef.current = settings.autoplay

  const currentTrack = playerState.queue[playerState.index] || null

  /** Restore volume/queue/shuffle/repeat from the previous session. */
  useEffect(() => {
    catMusicStore.hydrate()
  }, [])

  const clearErrorSkip = useCallback(() => {
    if (errorSkipRef.current) {
      clearTimeout(errorSkipRef.current)
      errorSkipRef.current = null
    }
  }, [])

  /** Writes the outgoing track to the listening history. */
  const commitHistory = useCallback((track: Track | null, seconds: number, completed: boolean) => {
    if (!track) return
    const ms = Math.round(Math.max(0, seconds) * 1000)
    if (!completed && ms < MIN_HISTORY_MS) return
    recordPlayRef.current(track, ms, completed)
  }, [])

  /** Loads a queue position into the iframe, recording the outgoing track. */
  const goToIndex = useCallback(
    (nextIndex: number, options: { play?: boolean; completed?: boolean } = {}) => {
      const { play = true, completed = false } = options
      const s = catMusicStore.getSnapshot()
      const outgoing = s.queue[s.index] || null
      const target = s.queue[nextIndex]
      if (!target) return

      clearErrorSkip()
      if (outgoing && outgoing.id !== target.id) {
        commitHistory(outgoing, completed ? s.duration || s.position : s.position, completed)
      }

      const yt = ytPlayerRef.current
      if (yt?.loadVideoById) {
        if (play) yt.loadVideoById(target.id)
        else yt.cueVideoById?.(target.id)
      }
      catMusicStore.setState({ index: nextIndex, position: 0, isPlaying: play, error: null })
    },
    [clearErrorSkip, commitHistory],
  )

  const handleTrackEnded = useCallback(() => {
    const s = catMusicStore.getSnapshot()
    const ended = s.queue[s.index] || null

    if (s.repeat === 'one') {
      commitHistory(ended, s.duration || s.position, true)
      const yt = ytPlayerRef.current
      if (yt?.seekTo) {
        yt.seekTo(0, true)
        yt.playVideo?.()
      }
      catMusicStore.setState({ position: 0, isPlaying: true })
      return
    }

    const isLast = s.index + 1 >= s.queue.length

    // `autoplay: false` means "stop when this track ends" — but an explicit
    // repeat setting is a stronger, more specific signal, so it still wins.
    if (!autoplayRef.current && s.repeat === 'off') {
      commitHistory(ended, s.duration || s.position, true)
      catMusicStore.setState({ isPlaying: false, position: 0 })
      return
    }

    if (isLast && s.repeat !== 'all') {
      commitHistory(ended, s.duration || s.position, true)
      catMusicStore.setState({ isPlaying: false, position: 0 })
      return
    }

    goToIndex(isLast ? 0 : s.index + 1, { play: true, completed: true })
  }, [commitHistory, goToIndex])

  const nextTrack = useCallback(() => {
    const s = catMusicStore.getSnapshot()
    if (s.queue.length === 0) return
    const isLast = s.index + 1 >= s.queue.length

    // A manual press always advances, even under `repeat: 'one'` — trapping the
    // user on one track would make the button look broken. At the very end,
    // only `repeat: 'all'` wraps around; otherwise playback stops.
    if (isLast && s.repeat !== 'all') {
      clearErrorSkip()
      const yt = ytPlayerRef.current
      commitHistory(s.queue[s.index] || null, s.position, false)
      yt?.pauseVideo?.()
      yt?.seekTo?.(0, true)
      catMusicStore.setState({ isPlaying: false, position: 0 })
      return
    }

    goToIndex(isLast ? 0 : s.index + 1)
  }, [clearErrorSkip, commitHistory, goToIndex])

  const previousTrack = useCallback(() => {
    const s = catMusicStore.getSnapshot()
    if (s.queue.length === 0) return
    if (s.position > 3) {
      ytPlayerRef.current?.seekTo?.(0, true)
      catMusicStore.setState({ position: 0 })
      return
    }
    const prevIdx = s.index - 1 < 0 ? s.queue.length - 1 : s.index - 1
    goToIndex(prevIdx)
  }, [goToIndex])

  // The player lives in a hidden container outside the React tree so a re-render
  // can never unmount the iframe mid-song.
  useEffect(() => {
    if (!active) return
    let mounted = true

    loadYouTubeIframeApi().then((YT) => {
      if (!mounted || ytPlayerRef.current) return

      let container = document.getElementById('cat-music-yt-container')
      if (!container) {
        container = document.createElement('div')
        container.id = 'cat-music-yt-container'
        container.style.position = 'fixed'
        container.style.top = '-9999px'
        container.style.left = '-9999px'
        container.style.width = '1px'
        container.style.height = '1px'
        container.style.opacity = '0'
        container.style.pointerEvents = 'none'
        container.style.zIndex = '-9999'
        const iframeTarget = document.createElement('div')
        iframeTarget.id = 'cat-music-yt-iframe'
        container.appendChild(iframeTarget)
        document.body.appendChild(container)
      }

      // Read the queue at init time instead of depending on `currentTrack`:
      // re-running this effect per track change would rebuild the iframe.
      const bootTrack = (() => {
        const s = catMusicStore.getSnapshot()
        return s.queue[s.index] || null
      })()

      try {
        ytPlayerRef.current = new YT.Player('cat-music-yt-iframe', {
          height: '200',
          width: '200',
          videoId: bootTrack ? bootTrack.id : SEED_TRACKS[0].id,
          playerVars: {
            autoplay: 0,
            controls: 0,
            disablekb: 1,
            modestbranding: 1,
            playsinline: 1,
            rel: 0,
            origin: typeof window !== 'undefined' ? window.location.origin : '',
          },
          events: {
            onReady: () => {
              const s = catMusicStore.getSnapshot()
              ytPlayerRef.current?.setVolume?.(s.volume)
              if (s.muted) ytPlayerRef.current?.mute?.()
            },
            onStateChange: (event: any) => {
              if (event.data === 1) {
                catMusicStore.setState({ isPlaying: true, isBuffering: false, error: null })
              } else if (event.data === 2) {
                catMusicStore.setState({ isPlaying: false, isBuffering: false })
              } else if (event.data === 3) {
                catMusicStore.setState({ isBuffering: true })
              } else if (event.data === 0) {
                handlersRef.current.handleTrackEnded()
              }
            },
            onError: () => {
              catMusicStore.setState({ isBuffering: false, error: 'unavailable' })
              if (errorSkipRef.current) clearTimeout(errorSkipRef.current)
              errorSkipRef.current = setTimeout(() => {
                errorSkipRef.current = null
                handlersRef.current.nextTrack()
              }, ERROR_SKIP_DELAY_MS)
            },
          },
        })
      } catch {
        // A blocked or sandboxed iframe must not take the whole app down.
      }
    })

    return () => {
      mounted = false
    }
  }, [active])

  // Every pending timer has to die with the provider, or a skip fires into a
  // torn-down tree.
  useEffect(() => {
    return () => {
      if (errorSkipRef.current) clearTimeout(errorSkipRef.current)
      if (seekResetRef.current) clearTimeout(seekResetRef.current)
    }
  }, [])

  // A timer, not requestAnimationFrame: rAF is frozen in a background tab, so
  // the progress bar and the OS scrubber used to stall while audio kept going.
  useEffect(() => {
    if (!active || !playerState.isPlaying) return

    const id = setInterval(() => {
      const yt = ytPlayerRef.current
      if (!yt || typeof yt.getCurrentTime !== 'function' || isSeekingRef.current) return

      const s = catMusicStore.getSnapshot()
      const position = yt.getCurrentTime() || 0
      const duration = yt.getDuration?.() || s.queue[s.index]?.durationSeconds || 0

      if (Math.abs(s.position - position) >= 0.25 || s.duration !== duration) {
        catMusicStore.setState({ position, duration })
      }

      if (duration > 0 && typeof navigator !== 'undefined' && 'mediaSession' in navigator) {
        try {
          navigator.mediaSession.setPositionState?.({
            duration,
            position: Math.min(position, duration),
            playbackRate: 1,
          })
        } catch {
          // Safari rejects a position past the duration; not worth reporting.
        }
      }
    }, TICK_MS)

    return () => clearInterval(id)
  }, [active, playerState.isPlaying])

  const togglePlayPause = useCallback(() => {
    const yt = ytPlayerRef.current
    if (!yt) return
    clearErrorSkip()
    const s = catMusicStore.getSnapshot()

    if (s.isPlaying) {
      yt.pauseVideo?.()
      catMusicStore.setState({ isPlaying: false })
    } else {
      yt.playVideo?.()
      catMusicStore.setState({ isPlaying: true, error: null })
    }
  }, [clearErrorSkip])

  const seekTo = useCallback((seconds: number) => {
    isSeekingRef.current = true
    catMusicStore.setState({ position: seconds })
    ytPlayerRef.current?.seekTo?.(seconds, true)
    if (seekResetRef.current) clearTimeout(seekResetRef.current)
    seekResetRef.current = setTimeout(() => {
      seekResetRef.current = null
      isSeekingRef.current = false
    }, 300)
  }, [])

  const setVolume = useCallback((vol: number) => {
    const clamped = Math.max(0, Math.min(100, Math.round(vol)))
    if (clamped > 0) preMuteVolumeRef.current = clamped
    const yt = ytPlayerRef.current
    yt?.setVolume?.(clamped)
    // Dragging the slider off zero has to lift the iframe's own mute flag, or
    // the volume change applies to a still-silent player.
    if (clamped === 0) yt?.mute?.()
    else yt?.unMute?.()
    catMusicStore.setState({ volume: clamped, muted: clamped === 0 })
  }, [])

  const toggleMute = useCallback(() => {
    const s = catMusicStore.getSnapshot()
    const yt = ytPlayerRef.current

    if (s.muted) {
      // Unmuting from volume 0 has to restore an audible level, otherwise the
      // button reports "unmuted" and nothing comes out.
      const restored = s.volume > 0 ? s.volume : preMuteVolumeRef.current || FALLBACK_UNMUTE_VOLUME
      yt?.unMute?.()
      yt?.setVolume?.(restored)
      catMusicStore.setState({ muted: false, volume: restored })
      return
    }

    if (s.volume > 0) preMuteVolumeRef.current = s.volume
    yt?.mute?.()
    catMusicStore.setState({ muted: true })
  }, [])

  const toggleShuffle = useCallback(() => {
    const s = catMusicStore.getSnapshot()
    if (!s.shuffle && s.queue.length > 1) {
      const currentTr = s.queue[s.index]
      const rest = s.queue.filter((_, i) => i !== s.index)
      for (let i = rest.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1))
        ;[rest[i], rest[j]] = [rest[j], rest[i]]
      }
      catMusicStore.setState({ shuffle: true, queue: [currentTr, ...rest], index: 0 })
      return
    }
    catMusicStore.setState({ shuffle: false })
  }, [])

  const cycleRepeat = useCallback(() => {
    const s = catMusicStore.getSnapshot()
    const currentIdx = REPEAT_MODES.indexOf(s.repeat)
    catMusicStore.setState({ repeat: REPEAT_MODES[(currentIdx + 1) % REPEAT_MODES.length] })
  }, [])

  const playTrack = useCallback(
    (track: Track, newQueue?: Track[], context?: { type: string; id?: string }) => {
      const s = catMusicStore.getSnapshot()
      // Copy: `newQueue` is often a caller's state array or a module constant,
      // and pushing into it mutated data nobody expected to change.
      const queue = [...(newQueue ?? s.queue)]

      let trackIndex = queue.findIndex((t) => t.id === track.id)
      if (trackIndex < 0) {
        queue.push(track)
        trackIndex = queue.length - 1
      }

      clearErrorSkip()
      const outgoing = s.queue[s.index] || null
      if (outgoing && outgoing.id !== track.id) {
        commitHistory(outgoing, s.position, false)
      }

      catMusicStore.setState({
        queue,
        index: trackIndex,
        isPlaying: true,
        position: 0,
        duration: track.durationSeconds || 0,
        context: context || s.context,
        error: null,
      })

      ytPlayerRef.current?.loadVideoById?.(track.id)
    },
    [clearErrorSkip, commitHistory],
  )

  const addToQueue = useCallback((track: Track) => {
    const s = catMusicStore.getSnapshot()
    if (s.queue.some((t) => t.id === track.id)) return
    catMusicStore.setState({ queue: [...s.queue, track] })
  }, [])

  const removeFromQueue = useCallback(
    (idx: number) => {
      const s = catMusicStore.getSnapshot()
      if (idx < 0 || idx >= s.queue.length) return

      const removingCurrent = idx === s.index
      const newQ = s.queue.filter((_, i) => i !== idx)

      if (newQ.length === 0) {
        clearErrorSkip()
        ytPlayerRef.current?.stopVideo?.()
        catMusicStore.setState({
          queue: [],
          index: 0,
          isPlaying: false,
          isBuffering: false,
          position: 0,
          duration: 0,
        })
        return
      }

      let newIdx = s.index
      if (idx < s.index) newIdx -= 1
      if (newIdx >= newQ.length) newIdx = newQ.length - 1

      // Dropping the playing track used to leave the iframe on the old video
      // while the UI showed a different one.
      if (removingCurrent) {
        clearErrorSkip()
        const target = newQ[newIdx]
        const yt = ytPlayerRef.current
        if (s.isPlaying) yt?.loadVideoById?.(target.id)
        else yt?.cueVideoById?.(target.id)
        catMusicStore.setState({ queue: newQ, index: newIdx, position: 0, duration: 0 })
        return
      }

      catMusicStore.setState({ queue: newQ, index: newIdx })
    },
    [clearErrorSkip],
  )

  const clearQueue = useCallback(() => {
    const s = catMusicStore.getSnapshot()
    const keep = s.queue[s.index]
    catMusicStore.setState({ queue: keep ? [keep] : [], index: 0 })
  }, [])

  const stopPlayback = useCallback(() => {
    clearErrorSkip()
    const s = catMusicStore.getSnapshot()
    commitHistory(s.queue[s.index] || null, s.position, false)
    const yt = ytPlayerRef.current
    yt?.stopVideo?.()
    yt?.pauseVideo?.()
    catMusicStore.setState({
      queue: [],
      index: 0,
      isPlaying: false,
      isBuffering: false,
      position: 0,
      duration: 0,
      context: null,
      error: null,
    })
  }, [clearErrorSkip, commitHistory])

  // Bridge for the once-registered YouTube callbacks. Written in an effect
  // rather than during render: the iframe can only call back after mount, so
  // committing the latest handlers post-commit is both correct and lint-clean.
  const handlersRef = useRef({ handleTrackEnded, nextTrack })
  useEffect(() => {
    handlersRef.current = { handleTrackEnded, nextTrack }
  }, [handleTrackEnded, nextTrack])

  // First run only: adopt the saved default volume. A volume that came back from
  // storage is a real user choice and must not be overwritten.
  const defaultVolumeAppliedRef = useRef(false)
  useEffect(() => {
    if (!active || defaultVolumeAppliedRef.current) return
    if (catMusicStore.wasRestored('volume')) {
      defaultVolumeAppliedRef.current = true
      return
    }
    const preferred = settings.defaultVolume
    if (typeof preferred !== 'number' || preferred < 0 || preferred > 100) return
    if (preferred === catMusicStore.getSnapshot().volume) return
    defaultVolumeAppliedRef.current = true
    setVolume(preferred)
  }, [active, settings.defaultVolume, setVolume])

  // OS-level media controls (lock screen, media keys, headset buttons).
  useEffect(() => {
    if (!active || typeof navigator === 'undefined' || !('mediaSession' in navigator)) return

    const ms = navigator.mediaSession
    if (!currentTrack) {
      ms.metadata = null
      ms.playbackState = 'none'
      return
    }

    // Offer both sizes and label them honestly — the OS picks per surface, and
    // a lock screen given a 320x180 image tagged 512x512 renders it blurry.
    const artwork: MediaImage[] = [
      {
        src: getArtworkUrl(currentTrack.id, 'mq'),
        sizes: ARTWORK_DIMENSIONS.mq,
        type: 'image/jpeg',
      },
      {
        src: getArtworkUrl(currentTrack.id, 'hq'),
        sizes: ARTWORK_DIMENSIONS.hq,
        type: 'image/jpeg',
      },
    ]

    ms.metadata = new MediaMetadata({
      title: currentTrack.title,
      artist: currentTrack.artist,
      album: currentTrack.album || 'CatMusic',
      artwork: currentTrack.source === 'youtube' ? artwork : [{ src: currentTrack.artworkUrl }],
    })

    // Each action gets its own handler: mapping play and pause both to a toggle
    // desynced the OS widget whenever it and the app disagreed on state.
    const handlers: [MediaSessionAction, MediaSessionActionHandler][] = [
      [
        'play',
        () => {
          if (!catMusicStore.getSnapshot().isPlaying) togglePlayPause()
        },
      ],
      [
        'pause',
        () => {
          if (catMusicStore.getSnapshot().isPlaying) togglePlayPause()
        },
      ],
      ['previoustrack', () => previousTrack()],
      ['nexttrack', () => nextTrack()],
      ['stop', () => stopPlayback()],
      [
        'seekbackward',
        (details) => {
          const by = details?.seekOffset ?? 10
          seekTo(Math.max(0, catMusicStore.getSnapshot().position - by))
        },
      ],
      [
        'seekforward',
        (details) => {
          const by = details?.seekOffset ?? 10
          const s = catMusicStore.getSnapshot()
          seekTo(Math.min(s.duration || Number.MAX_SAFE_INTEGER, s.position + by))
        },
      ],
      [
        'seekto',
        (details) => {
          if (typeof details?.seekTime === 'number') seekTo(details.seekTime)
        },
      ],
    ]

    for (const [action, handler] of handlers) {
      try {
        ms.setActionHandler(action, handler)
      } catch {
        // Older browsers throw on unknown actions instead of ignoring them.
      }
    }

    return () => {
      for (const [action] of handlers) {
        try {
          ms.setActionHandler(action, null)
        } catch {
          // Same as above.
        }
      }
    }
  }, [active, currentTrack, nextTrack, previousTrack, seekTo, stopPlayback, togglePlayPause])

  // Keep the OS widget's play/pause icon in step with the app.
  useEffect(() => {
    if (!active || typeof navigator === 'undefined' || !('mediaSession' in navigator)) return
    navigator.mediaSession.playbackState = currentTrack
      ? playerState.isPlaying
        ? 'playing'
        : 'paused'
      : 'none'
  }, [active, currentTrack, playerState.isPlaying])

  return (
    <PlayerContext.Provider
      value={{
        playerState,
        currentTrack,
        playTrack,
        togglePlayPause,
        nextTrack,
        previousTrack,
        seekTo,
        setVolume,
        toggleMute,
        toggleShuffle,
        cycleRepeat,
        addToQueue,
        removeFromQueue,
        clearQueue,
        stopPlayback,
      }}
    >
      {children}
    </PlayerContext.Provider>
  )
}

const defaultPlayerContext: PlayerContextType = {
  playerState: {
    queue: [],
    index: 0,
    isPlaying: false,
    isBuffering: false,
    position: 0,
    duration: 0,
    volume: 80,
    muted: false,
    shuffle: false,
    repeat: 'off',
    context: null,
    error: null,
  },
  currentTrack: null,
  playTrack: () => {},
  togglePlayPause: () => {},
  nextTrack: () => {},
  previousTrack: () => {},
  seekTo: () => {},
  setVolume: () => {},
  toggleMute: () => {},
  toggleShuffle: () => {},
  cycleRepeat: () => {},
  addToQueue: () => {},
  removeFromQueue: () => {},
  clearQueue: () => {},
  stopPlayback: () => {},
}

export function useCatMusicPlayer() {
  const ctx = useContext(PlayerContext)
  return ctx || defaultPlayerContext
}

declare global {
  interface Window {
    YT: any
    onYouTubeIframeAPIReady?: () => void
  }
}

let iframeApiPromise: Promise<any> | null = null

/**
 * Idempotent YouTube IFrame Player API script loader.
 */
export function loadYouTubeIframeApi(): Promise<any> {
  if (iframeApiPromise) return iframeApiPromise

  iframeApiPromise = new Promise((resolve) => {
    if (typeof window === 'undefined') return
    if (window.YT && window.YT.Player) {
      return resolve(window.YT)
    }

    const prevReady = window.onYouTubeIframeAPIReady
    window.onYouTubeIframeAPIReady = () => {
      prevReady?.()
      resolve(window.YT)
    }

    const script = document.createElement('script')
    script.src = 'https://www.youtube.com/iframe_api'
    script.async = true
    document.head.appendChild(script)
  })

  return iframeApiPromise
}

export type ArtworkSize = 'maxres' | 'sd' | 'hq' | 'mq'

/**
 * Pixel dimensions each YouTube thumbnail variant is served at. Used to
 * declare honest `sizes` to the MediaSession API, which otherwise shows a
 * blurry cover in the OS media controls.
 */
export const ARTWORK_DIMENSIONS: Record<ArtworkSize, string> = {
  maxres: '1280x720',
  sd: '640x480',
  hq: '480x360',
  mq: '320x180',
}

const ARTWORK_FILENAME: Record<ArtworkSize, string> = {
  maxres: 'maxresdefault',
  sd: 'sddefault',
  hq: 'hqdefault',
  mq: 'mqdefault',
}

/**
 * Generates deterministic YouTube thumbnail URLs based on size.
 *
 * `mq` and `hq` are generated for every video on the CDN, so they never 404.
 * `sd` and `maxres` only exist for high-resolution uploads — request those
 * only where a broken image is acceptable or an onError fallback is wired up.
 */
export function getArtworkUrl(youtubeId: string, size: ArtworkSize = 'mq'): string {
  if (!youtubeId) return '/placeholder.svg'
  return `https://i.ytimg.com/vi/${youtubeId}/${ARTWORK_FILENAME[size] ?? ARTWORK_FILENAME.mq}.jpg`
}

/**
 * Formats duration seconds into mm:ss or hh:mm:ss.
 */
export function formatDuration(seconds: number): string {
  if (!seconds || isNaN(seconds)) return '0:00'
  const secs = Math.floor(seconds)
  const h = Math.floor(secs / 3600)
  const m = Math.floor((secs % 3600) / 60)
  const s = secs % 60
  const sStr = s < 10 ? `0${s}` : `${s}`

  if (h > 0) {
    const mStr = m < 10 ? `0${m}` : `${m}`
    return `${h}:${mStr}:${sStr}`
  }
  return `${m}:${sStr}`
}

export type PluginInstallProgress = {
  pluginId: string
  percent: number
}

export type PluginInstallerAPI = {
  install: (payload: {
    pluginId: string
    version: string
    downloadUrl: string
  }) => Promise<{ ok: boolean; pluginId: string; version: string; installDir: string }>
  onDownloadProgress: (callback: (progress: PluginInstallProgress) => void) => () => void
  getInstallPath: (pluginId: string) => Promise<string | null>
}

export function getPluginInstaller(): PluginInstallerAPI | null {
  if (typeof window === 'undefined') return null
  return (window as any).pluginInstaller ?? null
}

'use client'

import React, { createContext, useCallback, useContext, useEffect, useState } from 'react'
import type { CatChatPlugin, PluginRailTab } from './plugin-types'
import { catMusicPlugin } from './cat-music'
import { getRegisteredPlugins, registerPlugin, unregisterPlugin } from './plugin-registry'
import { getPluginInstaller } from './plugin-installer-client'

type PluginUpdateInfo = {
  available: boolean
  newVersion: string
  name: string
  releaseNotes?: string
  downloadUrl?: string
}

type PluginContextType = {
  registeredPlugins: CatChatPlugin[]
  installedPluginIds: string[]
  enabledPluginIds: string[]
  installingPluginId: string | null
  installProgressMap: Record<string, number>
  pluginUpdates: Record<string, PluginUpdateInfo>
  isPluginInstalled: (id: string) => boolean
  isPluginEnabled: (id: string) => boolean
  hasPluginUpdate: (id: string) => boolean
  getPluginUpdateInfo: (id: string) => PluginUpdateInfo | null
  installPlugin: (id: string, isUpdate?: boolean) => Promise<void>
  updatePlugin: (id: string) => Promise<void>
  dismissPluginUpdate: (id: string) => void
  refreshPluginUpdates: () => Promise<void>
  uninstallPlugin: (id: string) => void
  enablePlugin: (id: string) => void
  disablePlugin: (id: string) => void
  togglePlugin: (id: string) => void
  getActiveRailTabs: () => PluginRailTab[]
}

const PluginContext = createContext<PluginContextType | null>(null)

const STORAGE_KEY_ENABLED = 'cz-enabled-plugins'
const STORAGE_KEY_INSTALLED = 'cz-installed-plugins'
const PLUGIN_UPDATE_POLL_MS = 30_000

const BUNDLED_PLUGINS: Record<string, CatChatPlugin> = {
  'cat-music': catMusicPlugin,
}

const BUNDLED_PLUGIN_IDS = Object.keys(BUNDLED_PLUGINS)

const STABLE_ROOT_PROVIDERS = [
  { id: 'cat-music' as const, Provider: catMusicPlugin.rootProvider! },
]

/** Plugins that no longer ship: dropped from saved state and purged on load. */
const REMOVED_PLUGIN_IDS = [
  'survivor-shooter',
  'tps-shooter',
  'fortnite-builder',
  'polimarket',
  'tps-controls',
]

function loadPluginIdList(key: string): string[] {
  if (typeof window === 'undefined') return []
  try {
    const saved = localStorage.getItem(key)
    if (!saved) return []
    const parsed = JSON.parse(saved) as string[]
    return Array.isArray(parsed) ? parsed.filter((id) => !REMOVED_PLUGIN_IDS.includes(id)) : []
  } catch {
    return []
  }
}

function mergePluginLists(...lists: string[][]): string[] {
  return [...new Set(lists.flat())]
}

export function isElectronEnv(): boolean {
  if (typeof window === 'undefined') return false
  if (process.env.NODE_ENV === 'development') return true
  return Boolean(
    (window as any).electronAPI ||
      (window as any).ipcRenderer ||
      (window as any).releaseTool ||
      navigator.userAgent.toLowerCase().includes('electron')
  )
}

export function PluginProvider({ children, user }: { children: React.ReactNode; user?: any }) {
  // Derive user-scoped storage keys so each account has independent plugin state
  const userId = user?.id || ''
  const storageKeyInstalled = userId ? `cz-installed-plugins-${userId}` : STORAGE_KEY_INSTALLED
  const storageKeyEnabled = userId ? `cz-enabled-plugins-${userId}` : STORAGE_KEY_ENABLED
  const pluginVerKey = (pluginId: string) => userId ? `cz-plugin-ver-${pluginId}-${userId}` : `cz-plugin-ver-${pluginId}`

  // Installed plugins (default empty array - plugins must be installed from Plugin Hub)
  const [installedPluginIds, setInstalledPluginIds] = useState<string[]>([])
  const [enabledPluginIds, setEnabledPluginIds] = useState<string[]>([])
  const [storageReady, setStorageReady] = useState(false)

  useEffect(() => {
    if (typeof window === 'undefined') return

    const userInstalled = loadPluginIdList(storageKeyInstalled)
    const userEnabled = loadPluginIdList(storageKeyEnabled)
    const legacyInstalled = userId ? loadPluginIdList(STORAGE_KEY_INSTALLED) : []
    const legacyEnabled = userId ? loadPluginIdList(STORAGE_KEY_ENABLED) : []

    const mergedInstalled = mergePluginLists(userInstalled, legacyInstalled)
    const mergedEnabled = mergePluginLists(userEnabled, legacyEnabled)

    setInstalledPluginIds(mergedInstalled)
    setEnabledPluginIds(mergedEnabled)

    try {
      localStorage.setItem(storageKeyInstalled, JSON.stringify(mergedInstalled))
      localStorage.setItem(storageKeyEnabled, JSON.stringify(mergedEnabled))
      if (userId && legacyInstalled.length > 0) {
        localStorage.removeItem(STORAGE_KEY_INSTALLED)
        localStorage.removeItem(STORAGE_KEY_ENABLED)
      }
      for (const removedId of REMOVED_PLUGIN_IDS) {
        localStorage.removeItem(`cz-plugin-ver-${removedId}`)
        localStorage.removeItem(`cz-plugin-data-${removedId}`)
        if (userId) {
          localStorage.removeItem(`cz-plugin-ver-${removedId}-${userId}`)
          localStorage.removeItem(`cz-plugin-data-${removedId}-${userId}`)
        }
      }
      // Settings the Polimarket plugin left behind outside its own data key.
      localStorage.removeItem('cz-polimarket-seen-events')
      localStorage.removeItem('cz-polimarket-alerts')
      localStorage.removeItem('cz-polimarket-settings')
    } catch {
      // Ignore storage write errors
    }

    setStorageReady(true)
  }, [storageKeyInstalled, storageKeyEnabled, userId])

  const [installingPluginId, setInstallingPluginId] = useState<string | null>(null)
  const [installProgressMap, setInstallProgressMap] = useState<Record<string, number>>({})
  const [pluginUpdates, setPluginUpdates] = useState<Record<string, PluginUpdateInfo>>({})
  const [liveVersionMap, setLiveVersionMap] = useState<Record<string, string>>({})
  const [liveDownloadMap, setLiveDownloadMap] = useState<Record<string, string>>({})

  const refreshPluginUpdates = useCallback(async () => {
    try {
      const res = await fetch(`/api/plugins?_=${Date.now()}`, { cache: 'no-store' })
      const data = await res.json()
      if (data?.plugins && Array.isArray(data.plugins)) {
        const updatesMap: Record<string, PluginUpdateInfo> = {}
        const vMap: Record<string, string> = {}
        const dMap: Record<string, string> = {}
        for (const p of data.plugins) {
          const formattedRemote = p.version ? (p.version.startsWith('v') ? p.version : `v${p.version}`) : 'v1.0.0'
          vMap[p.id] = formattedRemote
          if (p.downloadUrl) dMap[p.id] = p.downloadUrl
          const installedVer = (localStorage.getItem(pluginVerKey(p.id)) || '1.0.0').replace(/^v/, '')
          const remoteVer = (p.version || '1.0.0').replace(/^v/, '')
          if (installedPluginIds.includes(p.id) && remoteVer !== installedVer) {
            updatesMap[p.id] = {
              available: true,
              newVersion: formattedRemote,
              name: p.name || p.id,
              releaseNotes: p.description,
              downloadUrl: p.downloadUrl,
            }
          }
        }
        setLiveVersionMap(vMap)
        setLiveDownloadMap(dMap)
        setPluginUpdates(updatesMap)
      }
    } catch {
      // Ignore network errors; next poll will retry
    }
  }, [installedPluginIds, pluginVerKey])

  // Poll GitHub Releases API to detect plugin updates in near real-time
  useEffect(() => {
    refreshPluginUpdates()
    const id = setInterval(refreshPluginUpdates, PLUGIN_UPDATE_POLL_MS)
    return () => clearInterval(id)
  }, [refreshPluginUpdates])

  useEffect(() => {
    const onFocus = () => refreshPluginUpdates()
    window.addEventListener('focus', onFocus)
    return () => window.removeEventListener('focus', onFocus)
  }, [refreshPluginUpdates])

  // Ensure bundled plugins stay registered (survives uninstall/reinstall cycles)
  useEffect(() => {
    for (const plugin of Object.values(BUNDLED_PLUGINS)) {
      registerPlugin(plugin)
    }
  }, [])

  // Persist installed and enabled plugins (user-scoped) — only after hydration
  useEffect(() => {
    if (!storageReady || typeof window === 'undefined') return
    localStorage.setItem(storageKeyInstalled, JSON.stringify(installedPluginIds))
  }, [installedPluginIds, storageReady, storageKeyInstalled])

  useEffect(() => {
    if (!storageReady || typeof window === 'undefined') return
    localStorage.setItem(storageKeyEnabled, JSON.stringify(enabledPluginIds))
  }, [enabledPluginIds, storageReady, storageKeyEnabled])

  const registered = getRegisteredPlugins()

  const isPluginInstalled = (id: string) => installedPluginIds.includes(id)
  const isPluginEnabled = (id: string) => isPluginInstalled(id) && enabledPluginIds.includes(id)
  const hasPluginUpdate = (id: string) => Boolean(pluginUpdates[id]?.available)
  const getPluginUpdateInfo = (id: string) => pluginUpdates[id] || null

  const installPlugin = async (id: string, isUpdate = false) => {
    if (installingPluginId === id) return

    if (isPluginInstalled(id) && !isUpdate) {
      enablePlugin(id)
      return
    }

    const bundled = BUNDLED_PLUGINS[id]
    if (bundled) registerPlugin(bundled)

    const installer = getPluginInstaller()
    const targetVersion = pluginUpdates[id]?.newVersion || liveVersionMap[id] || 'v0.0.1'

    if (installer) {
      let downloadUrl = pluginUpdates[id]?.downloadUrl || liveDownloadMap[id] || `/plugins/${id}/release.zip`
      if (downloadUrl.startsWith('/')) {
        downloadUrl = `${window.location.origin}${downloadUrl}`
      }
      setInstallingPluginId(id)
      setInstallProgressMap((prev) => ({ ...prev, [id]: 0 }))

      const unsubProgress = installer.onDownloadProgress((progress) => {
        if (progress.pluginId !== id) return
        setInstallProgressMap((prev) => ({ ...prev, [id]: progress.percent }))
      })

      try {
        await installer.install({
          pluginId: id,
          version: targetVersion,
          downloadUrl,
        })
      } catch (err) {
        console.warn(`[PluginProvider] Plugin package download notice for "${id}":`, err)
      } finally {
        unsubProgress()
        setInstallingPluginId(null)
        setInstallProgressMap((prev) => {
          const copy = { ...prev }
          delete copy[id]
          return copy
        })
      }
    }

    setInstalledPluginIds((prev) => (prev.includes(id) ? prev : [...prev, id]))
    setEnabledPluginIds((prev) => {
      if (prev.includes(id)) return prev
      return [...prev, id]
    })
    localStorage.setItem(pluginVerKey(id), targetVersion)

    setPluginUpdates((prev) => {
      const copy = { ...prev }
      delete copy[id]
      return copy
    })

    const plugin = registered.find((p) => p.metadata.id === id)
    plugin?.onEnable?.()
    await refreshPluginUpdates()
  }

  const updatePlugin = async (id: string) => {
    return installPlugin(id, true)
  }

  const dismissPluginUpdate = (id: string) => {
    setPluginUpdates((prev) => {
      const copy = { ...prev }
      delete copy[id]
      return copy
    })
  }

  const uninstallPlugin = (id: string) => {
    disablePlugin(id)
    if (!BUNDLED_PLUGIN_IDS.includes(id)) {
      unregisterPlugin(id)
    }
    setInstalledPluginIds((prev) => prev.filter((pId) => pId !== id))

    // Purge all persistent data associated with this plugin completely
    if (typeof window !== 'undefined') {
      try {
        localStorage.removeItem(`cz-plugin-data-${id}`)
        localStorage.removeItem(pluginVerKey(id))
        if (id === 'cat-music') {
          localStorage.removeItem('cz-catmusic-store')
          localStorage.removeItem('cz-catmusic-playlists')
          localStorage.removeItem('cz-catmusic-favorites')
          localStorage.removeItem('cz-catmusic-history')
        }
      } catch {
        // Ignore storage purge errors
      }
    }
  }

  const enablePlugin = (id: string) => {
    if (isPluginInstalled(id) && !enabledPluginIds.includes(id)) {
      const next = [...enabledPluginIds, id]
      setEnabledPluginIds(next)
      const plugin = registered.find((p) => p.metadata.id === id)
      plugin?.onEnable?.()
    }
  }

  const disablePlugin = (id: string) => {
    if (enabledPluginIds.includes(id)) {
      const next = enabledPluginIds.filter((pId) => pId !== id)
      setEnabledPluginIds(next)
      const plugin = registered.find((p) => p.metadata.id === id)
      plugin?.onDisable?.()
    }
  }

  const togglePlugin = (id: string) => {
    if (isPluginEnabled(id)) {
      disablePlugin(id)
    } else {
      enablePlugin(id)
    }
  }

  const getActiveRailTabs = (): PluginRailTab[] => {
    const tabs: PluginRailTab[] = []
    registered.forEach((plugin) => {
      const pluginId = plugin.metadata.id
      if (!isPluginEnabled(pluginId) || !plugin.railTabs?.length) return
      for (const tab of plugin.railTabs) {
        tabs.push(tab)
      }
    })

    const orderFor = (pluginId: string) => {
      const plugin = registered.find((p) => p.metadata.id === pluginId)
      return plugin?.railOrder ?? 100
    }

    return tabs.sort((a, b) => {
      const orderDiff = orderFor(a.id) - orderFor(b.id)
      if (orderDiff !== 0) return orderDiff
      return a.label.localeCompare(b.label)
    })
  }

  // Nest root providers in a fixed order so React never remounts children when plugins change
  let wrappedContent = <>{children}</>

  for (const { id, Provider } of [...STABLE_ROOT_PROVIDERS].reverse()) {
    wrappedContent = (
      <Provider key={id} user={user} active={installedPluginIds.includes(id)}>
        {wrappedContent}
      </Provider>
    )
  }

  return (
    <PluginContext.Provider
      value={{
        registeredPlugins: registered,
        installedPluginIds,
        enabledPluginIds,
        installingPluginId,
        installProgressMap,
        pluginUpdates,
        isPluginInstalled,
        isPluginEnabled,
        hasPluginUpdate,
        getPluginUpdateInfo,
        installPlugin,
        updatePlugin,
        dismissPluginUpdate,
        refreshPluginUpdates,
        uninstallPlugin,
        enablePlugin,
        disablePlugin,
        togglePlugin,
